       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3aa55775-4961-5ece-b8a1-bd8cf687e8e5","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -كفالة غرم وأداء -بيع فيا بأقساط -سداد املشتري جزء من الثمن والعجز عن سداد الباقي -قيام الكفيل بسداد ثمن ا -مطالبة الكفيل بسداد أتعاب احملاماة -النص يف الفيا كام العقد على حتمل املشتري أتعاب احملاماة -إقرار الكفيل بالكفالة وسداد مقابل أتعاب احملاماة -إثبات بشهادة الشهود -النكول لعدم حضور املدعى عليه دون عذر رغم التبليغ -القضاء على الناكل - إلزام الكفيل بسداد أتعاب احملاماة .","document_number":"34359043","case_number":"34164547","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/12","year":"1434","subject":"عقار -كفالة غرم وأداء -بيع فيا بأقساط -سداد املشتري جزء من الثمن والعجز عن سداد الباقي -قيام الكفيل بسداد ثمن ا -مطالبة الكفيل بسداد أتعاب احملاماة -النص يف الفيا كام العقد على حتمل املشتري أتعاب احملاماة -إقرار الكفيل بالكفالة وسداد مقابل أتعاب احملاماة -إثبات بشهادة الشهود -النكول لعدم حضور املدعى عليه دون عذر رغم التبليغ -القضاء على الناكل - إلزام الكفيل بسداد أتعاب احملاماة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34359043 :‬تاريخه‪1434/11/12 :‬هـ‬\n                          ‫رقم الدعوى‪34164547 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 35264899‬تاريخه‪1435/6/3 :‬هـ‬\n\n\n       ‫عقــار ‪ -‬كفالــة غــرم وأداء ‪ -‬بيــع فيــا بأقســاط ‪ -‬ســداد املشــتري جــزء‬\n       ‫مــن الثمــن والعجــز عــن ســداد الباقــي ‪ -‬قيــام الكفيــل بســداد ثمــن‬\n       ‫ا ‪ -‬مطالبــة الكفيــل بســداد أتعــاب احملامــاة ‪ -‬النــص يف‬    ‫الفيــا كام ـ ً‬\n       ‫العقــد علــى حتمــل املشــتري أتعــاب احملامــاة ‪ -‬إقــرار الكفيــل بالكفالــة‬\n       ‫وســداد مقابــل أتعــاب احملامــاة ‪ -‬إثبــات بشــهادة الشــهود ‪ -‬النكــول لعــدم‬\n       ‫حضــور املدعــى عليــه دون عــذر رغــم التبليــغ ‪ -‬القضــاء علــى النــاكل ‪-‬‬\n                                            ‫إلــزام الكفيــل بســداد أتعــاب احملامــاة ‪.‬‬\n\n\n\n\n           ‫‪ .1‬قوله صلى اهلل عليه وس ّلم (ال ضرر وال ضرار) رواه اإلمام أحمد‪.‬‬\n       ‫‪ .2‬قــال صاحــب شــرح املنتهــى‪( :‬وإن ســكت مدعــى عليــه) بــأن لــم يقــر‬\n       ‫بالدعــوى ولــم ينكرهــا (أو قــال) املدعــى عليــه‪( :‬ال أقــر وال أنكــر أو) قــال‪:‬‬\n       ‫(ال أعلــم قــدر حقــه وال بينــة) ملــدع بدعــواه ( قــال احلاكــم ) ملدعــى‬\n       ‫عليــه‪( :‬إن أجبــت وإال جعلتــك نــاكال وقضيــت عليــك) بالنكــول ‪.‬‬\n                                                                                     ‫‪ .).‬ا‪.‬هـ‬\n       ‫‪ .3‬ويف اإلنصــاف‪( :‬قولــه‪( :‬وإن ســكت املدعــى عليــه ‪ ،‬فلــم يقــر ولــم ينكــر‪،‬‬\n       ‫ال وقضيــت عليــك‪،‬‬      ‫قــال لــه القاضــي‪ :‬إن أجبــت ‪ ،‬وإال جعلتــك نــاك ً‬\n                                                                        ‫وهــو املذهــب) ا‪ .‬ه ـ‬\n       ‫‪ .4‬ومبــا أن للحاكــم واليــة علــى مــال الغائــب ويجــوز احلكــم عليــه‬\n       ‫وعلــى املســتتر واملمتنــع ولــو كان يف البلــد [ينظــر‪ :‬الفــروع ‪،268/11‬‬\n‫‪261‬‬\n\f                              ‫اإلنصــاف ‪ ،249/11‬كشــاف القنــاع ‪.]25/4‬‬\n‫‪ .5‬قــال صاحــب حتفــة احملتــاج يف شــرح املنهــاج‪( :‬وإال لتواريــه أو تعــززه‬\n‫البينــة ويحكــم بغيــر‬\n                    ‫أي‪ :‬تغلبــه وقــد ثبــت ذلــك عنــد القاضــي فتســمع ّ‬\n‫حضــوره مــن غيــر ميــن لالســتظهار علــى املنقــول املعتمــد تغليظ ـ ًا‬\n                                        ‫عليــه‪ ،‬وإال المتنــع ال َّنــاس ك ّلهــم) ‪.‬‬\n           ‫‪ .6‬املادة ‪ 55‬من نظام املرافعات الشرعية ولوائحه التنفيذية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن موكلــه بــداءة قــام ببيــع فيــا إلــى شــخص معــن‪،‬‬\n‫وقــد اتفــق الطرفــان مبوجــب عقــد علــى ســداد املبلــغ بأقســاط‪ ،‬قــام‬\n‫املشــتري بســداد جــزء مــن املبلــغ وعجــز عــن ســداد الباقــي‪ ،‬قــام البائــع‬\n‫بعمــل وكالــة إلــى محامــي لبيــع الفيــا باملــزاد العلنــي وإنهــاء اإلجــراءات‬\n‫املتعلقــة بذلــك نتيجــة صــدور حكــم بإلــزام املدعــى عليــه بســداد باقــي‬\n‫الثمــن‪ ،‬طلــب املشــتري إعطائــه مهلــة لســداد ثمــن الفيــا وأتعــاب‬\n‫احملامــاة‪ ،‬إال أنــه قــام (الكفيــل) بكفالــة غــرم وأداء للمدعــى عليــه‬\n‫ا ولــم يســدد أجــرة احملامــاة‪ ،‬لــذا طلــب إلــزام‬\n                                                    ‫وســدد ثمــن الفيــا كامـ ً‬\n‫املدعــى عليــه (الكفيــل) بســداد أتعــاب احملامــاة املنصــوص عليهــا‬\n‫يف العقــد‪ ،‬دفــع املدعــى عليــه بانتفــاء صفــة املدعــي يف الدعــوى ألن‬\n‫ـاء علــى العقــد بــن املشــتري والبائــع والكفالــة‬    ‫الكفالــة نشــأت بنـ ً‬\n‫حــررت ملصلحــة البائــع‪ ،‬قــدم املدعــي العقــد منصــوص فيــه علــى حتمــل‬\n‫املشــتري أتعــاب محامــاة وكيــل البائــع‪ ،‬كمــا قــدم بينــة لذلــك إقــرار‬\n‫املدعــى عليــه بالكفالــة وحتمــل ســداد مقابــل أتعــاب احملامــاة‪ ،‬كمــا‬\n‫قــدم شــاهدين شــهدا مبــا ســبق‪ ،‬لــم يحضــر املدعــى عليــه اجللســات‬\n\n                                                                                       ‫‪262‬‬\n\f      ‫دون عــذر رغــم تبليغــه ممــا يعــد نــاكالً‪ ،‬وترتيب ـ ًا علــى مــا تقــدم وملــا‬\n      ‫كان النــاكل يقضــى عليــه وألن عــدم احلضــور فيــه إضــرار باملدعــي‬\n      ‫حكمــت احملكمــة بإلــزام املدعــى عليــه بســداد مبلــغ أتعــاب احملامــاة‬\n      ‫للمدعــي ‪ ،‬مت مصادقــة احلكــم مــن محكمــة االسـ ـ ــتئناف مبنطقــة‬\n                                                                      ‫مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة‪ ،‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جــدة برقــم‪ 34164547 :‬وتاريــخ‪:‬‬\n      ‫‪1434/04/09‬ه ـ املقيــدة باحملكمــة برقــم‪ 34874869 :‬وتاريــخ‪:‬‬\n      ‫‪1434/04/09‬ه ـ ففــي يــوم الثالثــاء املوافــق‪1434/10/20 :‬ه ـ حضــر‪:‬‬\n      ‫‪ .......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪....... :‬وحضــر‬\n      ‫حلضــوره‪ ....... :‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪....... :‬‬\n      ‫الوكيــل عــن‪....... :‬بصفتــه وكيــا عــن‪....... :‬بصفتــه الشــخصية‬\n      ‫وبصفتــه املديــر التنفيــذي لشــركة ‪.......‬احملــدودة مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة بجــدة برقــم‪ 34393937 :‬يف‪:‬‬\n      ‫‪1434/04/01‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة واإلقــرار‬\n      ‫واإلنــكار والصلــح وطلــب اليمــن واالســتالم والتســليم‪ .‬ا‪ .‬ه ـ وادعــى‬\n      ‫األول قائــا‪ :‬إن ‪.......‬ميلــك الفيــا الواقعــة يف حــي الشــاطئ بجدة بالصك‬\n      ‫رقــم‪ 1162 :‬يف‪1421/07/21 :‬ه ـ وقــد باعهــا علــى شــخص اســمه‪:‬‬\n      ‫م‪ .......‬بقيمــة قدرهــا‪ :‬تســعة ماليــن ريــال ‪ ،‬اســتلم منهــا البائــع مبلغــا‬\n      ‫قــدره‪ :‬خمســة ماليــن ريــال ولــم يســدد املشــتري باقــي ثمــن املبيــع‪ ،‬وقــد‬\n\n‫‪263‬‬\n\f‫ترافعــت عــن البائــع يف مطالبــة املشــتري بباقــي الثمــن وصــدر حكــم‬\n‫مــن هــذه احملكمــة برقــم‪ 3/200/334 :‬يف‪1429/10/15 :‬ه ـ‬\n‫واملتضمــن‪ :‬إلــزام املشــتري بتســديد باقــي الثمــن وقــدره‪ :‬أربعــة ماليــن‬\n‫ريــال‪ ،‬وأثنــاء إجــراءات التنفيــذ توجــه بيــع العقــار باملــزاد العلنــي فطلــب‬\n‫املشــتري مهلــة مــن البائــع لتســديد باقــي ثمــن املبيــع وقــدره‪ :‬أربعة ماليني‬\n‫ريــال وكــذا تســديد أتعابــي يف املرافعــة يف هــذه القضيــة وقدرهــا‪ :‬ســت‬\n‫مئــة ألــف ريــال فتــم االتفــاق علــى ذلــك‪ ،‬وقــد كفــل املشــتري كفالــة‬\n‫غــرم وأداء املدعــى عليــه‪ .......... :‬وقــد ســدد املشــتري باقــي ثمــن املبيــع‬\n‫ولــم يســدد لــي أجــرة احملامــاة‪ ،‬ومبــا أن املدعــى عليه قد كفل املشــتري‬\n‫كفالــة غــرم وأداء فإنــي أطلــب إلــزام املدعــى عليــه بتســليم كامــل‬\n‫املبلــغ املتفــق عليــه وقــدره‪ :‬ســت مئــة ألــف ريــال‪ ،‬هكــذا ادعــى‪ .‬وبعــرض‬\n‫ذلــك علــى املدعــى عليــه وكالــة أجــاب قائــا‪ :‬أطلــب مهلة ملدة أســبوعني‬\n‫للرجــوع ملوكلــي واإلجابــة علــى الدعــوى‪ ،‬هكــذا أجــاب‪ .‬ثــم قــرر‬\n‫املدعــي قائــا‪ :‬إننــي أقمــت األخ‪ ،.......... :‬ســعودي اجلنســية مبوجــب‬\n‫الهويــة الوطنيــة رقــم‪....... :‬وكيــا ينــوب عنــي يف الترافــع يف هــذه‬\n‫القضيــة ومــا يتفــرع منهــا ولــه حــق املرافعــة واملدافعــة واإلقــرار واإلنكار‬\n‫والصلــح وطلــب اليمــن وردهــا‪ .‬ا‪ .‬هــ‪ .‬ويف يــوم األربعــاء املوافــق‪:‬‬\n‫‪1434/11/05‬ه ـ حضــر‪ ،....... :‬ســعودي اجلنســية مبوجــب الهويــة‬\n‫الوطنيــة رقــم‪....... :‬الوكيــل عــن‪....... :‬مبوجــب الوكالــة املثبتــة لدينــا يف‬\n‫ضبــط اجللســة الســابقة واملخــول لــه فيهــا حــق‪ :‬املرافعــة واملدافعــة‬\n‫واإلقــرار واإلنــكار والصلــح وطلــب اليمــن وردها‪ .‬ا‪ .‬ه ـ وحضر حلضوره‬\n‫املدعــى عليــه وكالــة‪....... :‬املثبــت حضــوره يف جلســة ســابقة‪ ،‬وبســؤال‬\n‫املدعــى عليــه وكالــة عمــا اســتمهل مــن أجــاب قائــا‪ :‬أدفــع بدفــع‬\n\n\n                                                                                       ‫‪264‬‬\n\f      ‫شــكلي وهــو أن املدعــي أصالــة ليــس لــه صفة يف الدعــوى‪ ،‬إذ الكفالة‬\n      ‫نشــأت بنــاء علــى العقــد الــذي بــن املشــتري ‪ ......‬وبــن البائــع ‪......‬‬\n      ‫والكفالــة حــررت ملصلحــة البائــع ‪.......‬فــا صفــة للمدعــي هنــا إذ ال‬\n      ‫عالقــة بينــه وبــن موكلــي‪ ،‬هكــذا أجــاب‪ .‬وبســؤاله عــن اجلــواب عــن‬\n      ‫موضــوع الدعــوى أجــاب قائــا‪ :‬أطلــب مهلــة للرجــوع ملوكلــي‪ ،‬هكــذا‬\n      ‫أجــاب‪ .‬ويف يــوم األربعــاء املوافــق‪1434/11/12 :‬ه ـ حضــر املدعــي‬\n      ‫وكالــة‪....... :‬املثبــت حضــوره يف جلســة ســابقة‪ ،‬ولــم يحضــر املدعــى‬\n      ‫عليــه‪....... :‬وال مــن ميثلــه رغــم تبلــغ وكيلــه مبوعــد هــذه اجللســة حســب‬\n      ‫توقيعــه علــى ضبــط اجللســة الســابقة‪ ،‬وبســؤال املدعــي وكالــة عــن‬\n      ‫بينتــه أجــاب قائــا‪ :‬بينتــي ورقــة االتفــاق بــن ‪..............‬وجــرى اطالعنــا‬\n      ‫عليهــا وهــذا نصهــا‪( :‬اتفاقيـ ــة‪ ،‬احلمد هلل والصالة والســام على ســيدنا‬\n      ‫محمــد وعلــى آلــه وصحبــه أجمعــن‪ ،‬أمــا بعــد‪ ،‬إنــه يف يــوم اخلميــس‬\n      ‫‪1432/01/24‬هــ‪ ،‬املوافــق ‪2010/12/30‬م‪ ،‬مت االتفــاق والتراضــي‪،‬‬\n      ‫كل مــن‪ :‬أوالً‪ :‬ا ُملكـ َّـرم‪ ،....... /‬ســعودي‬\n                                                   ‫بعــد عــون اهلل وتوفيقــه ‪ ،‬بــن ٍ‬\n      ‫اجلنســية‪ ،‬ســجل مدنــي رقــم (‪ ).......‬ميثلــه يف التوقيــع علــى هــذه االتفاقيــة‬\n      ‫احملامــي‪ ،....... /‬بصفتــه وكيلــه الشــرعي‪ .‬عنوانــه‪ :‬جــدة ‪ ،‬شــركة‬\n      ‫‪.......‬و‪ .......‬للمحامــاة ‪ ،‬مركــز ‪.......‬لألعمــال الــدور اخلامــس مكتــب‬\n      ‫ويشــار إليــه فيمــا‬\n                         ‫(‪ ).......‬هاتــف‪ ،....... :‬فاكــس‪ ،....... :‬جــوال‪ُ ،....... :‬‬\n      ‫بعــد بالطــرف األول ثاني ـاً‪ :‬ا ُملكـ َّـرم‪ ،....... /‬ســعودي اجلنســية‪ ،‬ســجل‬\n      ‫مدنــي رقــم (‪ ).......‬عنوانــه املختــار مكتــب األســتاذ ‪.......‬الواقــع بجــدة‬\n      ‫طريــق امللــك بنايــة ‪.......‬الــدور األول ‪ ،‬ص‪.‬ب‪....... :‬رمــز بريــدي‪،....... :‬‬\n      ‫ويشــار إليــه‬‫مدينــة جــدة ‪ ،‬هاتــف‪ ،....... :‬فاكــس‪....... :‬جــوال‪ُ ،....... :‬‬\n      ‫فيمــا بعــد بالطــرف الثانــي ‪،‬متهيـ ــد‪ :‬مل ــا كان الطــرف الثانــي مدين ـ ًا‬\n\n\n‫‪265‬‬\n\f‫للطــرف األول مببلــغ قــدره (‪ 4,000,000‬ريــال) أربعــة ماليــن ريــال‬\n‫ســعودي‪ .‬مبوجــب احلكــم الصــادر مــن احملكمــة العامــة بجــدة برقــم‬\n‫(‪ )3/200/334‬وتاريــخ ‪1429/10/15‬ه ـ ‪ ،‬وحيــث يعمــل الطــرف األول‬\n‫علــى إجــراءات بيــع الفيــا اململوكــة مبوجــب الصــك الصــادر مــن‬\n‫كتابــة عــدل جــدة برقــم ‪ 1162‬وتاريــخ ‪1412/7/21‬هــ‪ ،‬باملــزاد العلنــي‬\n‫بغــرض تنفيــذ احلكــم املشــار إليــه أعــاه؛ وذلــك عــن طريــق قاضــي‬\n‫التنفيــذ باحملكمــة العامــة بجــدة ‪ ،‬وحيــث طلــب الطــرف الثانــي مــن‬\n‫الطــرف األول التريــث يف بيــع الفيــا املشــار إليهــا أعــاه‪ ،‬وإمهالــه فقــط‬\n‫مــدة (‪ 100‬يــوم) مائــة يــوم مــن تاريــخ إبــرام هــذه االتفاقيــة‪ ،‬لســداد‬\n‫كامــل مبلــغ املديونيــة البالغــة أربعــة ماليــن ريــال ســعودي‪ ،‬وكذلــك‬\n‫دفــع مبلــغ (‪ 600,000‬ريــال) ســتمائة ألــف ريــال ســعودي‪ ،‬لوكيــل‬\n‫الطــرف األول شــركة ‪.......‬و‪ .......‬للمحامــاة ممثلــة يف احملامــي‪....... /‬‬\n‫كأتعــاب محامــاة‪ ،‬وحيــث صادفــت رغبــة الطــرف الثانــي قبــو ًال لــدى‬\n‫الطــرف األول عليــه فقــد اتفــق الطرفــان‪ ،‬وهما بكامــل األهلية املعتبرة‬\n‫ـاب وقبــولٍ صحيحــن؛‬    ‫شــرعاً‪ ،‬ونظامـاً‪ ،‬علــى إبــرام هــذه االتفاقيــة بإيجـ ٍ‬\n‫لتحكــم العالقــة الناشــئة بينهمــا‪ ،‬وفق ـ ًا للبنــود والشــروط التاليــة‪-1:‬‬\n‫يعتبــر التمهيــد أعــاه أساس ـ ًا لهــذه االتفاقيــة‪ ،‬وجــزء ًا ال يتجــزأ منــه‪،‬‬\n‫ومتممـ ًا ألحكامهــا‪ ،‬ومفســر ًا لبنودهــا ‪ -2‬منــح الطــرف األول للطــرف‬\n‫الثانــي مبوجــب هــذه االتفاقيــة مهلــة قدرهــا فقــط (‪ 100‬يــوم) مائــة يــوم‬\n‫تبــدأ مــن تاريــخ إبــرام هــذه االتفاقيــة وتنتهــي حتديــد ًا يف تاريــخ‬\n‫‪1432/05/06‬ه ـ املوافــق ‪2011/04/10‬م وذلــك لســداد كامــل‬\n‫املديونيــة التــي عليــه وكذلــك كامــل أتعــاب وكيلــه الشــرعي احملامــي‬\n‫‪.......‬التــي التــزم بهــا ‪-3‬مبوجــب هــذه االتفاقيــة يقــوم الطــرف األول‬\n\n\n                                                                                      ‫‪266‬‬\n\f      ‫بتقــدمي خطــاب للحقــوق املدنيــة بجــدة يطلــب فيــه رفــع اســم الطــرف‬\n      ‫الثانــي مــن قائمــة املطلوبــن‪ ،‬ملــدة مائــة يــوم فقــط‪ ،‬ليتمكــن الطــرف‬\n      ‫الثانــي مــن تدبيــر أمــوره ويلتــزم الطــرف الثانــي بواســطة وكالئــه‬\n      ‫مبتابعــة اخلطــاب املقــدم مــن الطــرف األول حلــن حتقــق الرفــع‪ ،‬واتفــق‬\n      ‫الطرفــان علــى أن تأخــر اجلهــات املختصــة يف رفــع اســم الطــرف الثانــي‬\n      ‫مــن قائمــة املطلوبــن أو عــدم املوافقــة عليــه ألي ســبب كان‪ ،‬ال ُيعـ ّـد وال‬\n      ‫ُيعتبــر إخــا ًال مــن قبــل الطــرف األول حيــث إن دوره ينتهــي مبجــرد تقــدمي‬\n      ‫اخلطــاب املذكــور وقيــده لــدى احلقــوق املدنيــة أو شــرطة احملافظــة‬\n      ‫بحســب األحــوال‪ ،‬كمــا اتفقــا صراحـ ًة علــى أن تأخــر اجلهــات املختصــة‬\n      ‫يف رفــع اســم الطــرف الثانــي مــن قائمــة املطلوبــن أو رفضهــا لذلــك ليــس‬\n      ‫لــه أي تأثيــر علــى احلقــوق وااللتزامــات الــواردة يف هــذه االتفاقيــة وليــس‬\n      ‫لــه كذلــك أي تأثيــر علــى املهلــة احملــددة ‪-4‬مبوجــب هــذه االتفاقيــة‬\n      ‫يلتــزم الطــرف الثانــي بــأن ُيســدد خــال مــدة أقصاهــا مائــة يــوم مــن‬\n      ‫تاريــخ إبــرام هــذه االتفاقيــة املبالــغ التاليــة‪ :‬مبلــغ (‪ 4,000,000‬ريــال)‬\n      ‫أربعــة ماليــن ريــال ســعودي للطــرف األول؛ تنفيــذ ًا للحكــم املشــار إليــه‬\n      ‫يف التمهيــد أعــاه ومبلــغ (‪ 600,000‬ريــال) ســتمائة ألــف ريــال ســعودي‪،‬‬\n      ‫لوكيــل الطــرف األول شــركة ‪....... .......‬للمحامــاة واالستشــارات‬\n      ‫القانونية ممثلة يف احملامي‪....... /‬؛ كأتعاب محاماة ‪-5‬اتفق الطرفان‬\n      ‫علــى بقــاء اســم الفيــا باســم الطــرف األول حلــن قيــام الطــرف الثانــي‬\n      ‫بســداد كامــل املبالــغ احملــددة أعــاه ‪ ،‬وعندهــا يتــم إفــراغ الفيــا‬\n      ‫للطــرف الثانــي ‪-6‬يف حالــة تخلــف الطــرف الثانــي عــن ســداد كل أو‬\n      ‫بعــض املبالــغ احملــددة أعــاه‪ ،‬خــال املهلــة احملــددة لــه يف هــذه االتفاقيــة‬\n      ‫فــإن الطرفــن اتفقــا علــى أن يكــون للطــرف األول ‪-‬وحــده‪ -‬اخليــار بــن‬\n\n\n‫‪267‬‬\n\f‫فســخ عقــد بيــع الفيــا املشــار إليهــا أعــاه واعتبــاره كأن لــم يكــن‬\n‫ويقــوم الطــرف األول علــى إثــر ذلــك باســترداد الفيــا‪ ،‬وإعــادة املبالــغ‬\n‫التــي دفعــت لــه مــن قبــل الطــرف الثانــي حتــت حســاب ثمــن الفيــا‪،‬‬\n‫وذلــك بعــد قيــام الطــرف األول ببيــع الفيــا املذكــورة لشــخص آخــر‪،‬‬\n‫وبعــد خصــم مبلــغ (‪ 2,000,000‬ريــال) مليونــي ريــال مقابــل انتفــاع‬\n‫واســتغالل الطــرف الثانــي للفيــا املذكــورة خــال الفتــرة مــن تاريــخ‬\n‫اســتالمه لهــا وحتــى تاريــخ انتهــاء املهلــة احملــددة يف هــذه االتفاقيــة‪،‬‬\n‫وكذلــك خصــم مبلــغ (‪ 600,000‬ريــال) عــن أتعــاب احملامــاة التــي التــزم‬\n‫الطــرف الثانــي بدفعهــا للمحامــي ‪ .......‬وبــن بيعهــا باملــزاد العلنــي عــن‬\n‫طريــق قاضــي التنفيــذ أو بــأي طريقــة أخــرى يراهــا الطــرف األول‬\n‫مناســبة الســتيفاء دينــه‪ ،‬وأتعــاب وكيلــه احملامــي ‪.......‬احملــددة أعــاه‪،‬‬\n‫ومــن ثــم يقــوم بــرد مــا يزيــد مــن ثمــن البيــع للطــرف الثانــي‪ ،‬ويف حالــة‬\n‫عــدم تغطيــة ثمــن البيــع للمديونيــة وأتعــاب احملامــاة املذكــورة‪ ،‬فتبقــى‬\n‫ذمــة الطــرف الثانــي مشــغولة بالفــرق لصالــح الطــرف األول ووكليــه‬\n‫املذكــور‪ ..‬ويف جميــع األحــوال؛ يلتــزم الطــرف الثانــي فــور انتهــاء املهلــة‬\n‫احملــددة لــه بإخــاء الفيــا املذكــورة خــال مــدة أقصاهــا أســبوع‬\n‫واحــد‪ ،‬ليتولــى الطــرف األول تنفيــذ أحــد اخلياريــن املذكوريــن أعــاه‬\n‫‪-7‬يقــر كل طــرف بــأن العنــوان املبــن يف صــدر هــذه االتفاقيــة هــو‬       ‫ُ‬\n‫العنــوان الدائــم لــه‪ ،‬وأن كل مــا ُيرســل علــى عنوانــه املذكــور ملــزم‬\n‫لــه‪ ،‬ومنتــج آلثــاره الشــرعية‪ ،‬والنظاميــة ‪-8‬أي نــزاع قــد ينشــا بــن‬\n‫الطرفــن ال ســمح اهلل يفصــل فيــه عــن طريــق احملاكــم املختصــة‬\n‫مبدينــة جــدة ووفقــا ألحــكام الشــريعة االســامية وانظمــة وقوانــن‬\n‫‪-9‬حــررت هــذه االتفاقيــة مــن نســختني‪،‬‬      ‫اململكــة العربيــة الســعودية ُ‬\n\n                                                                                      ‫‪268‬‬\n\f      ‫بيــد كل طــرف نســخة؛ للعمــل مبوجبهــا عنــد اللــزوم‪ ..‬وبــاهلل الثقــة‪،‬‬\n      ‫وعليــه االتــكال‪ ،،‬الطــرف االول ‪ .......‬بالوكالــة (التوقيــع ) ‪ ،‬الطــرف‬\n      ‫الثاني ‪ ( .......‬التوقيع) الشاهد (‪ ،....... )1‬سجل مدني (‪( ).......‬التوقيع)‬\n      ‫‪ ،‬الشــاهد (‪( ....... )2‬التوقيــع)‪ .‬ا‪ .‬ه ـ وبســؤال املدعــي وكالــة عــن زيــادة‬\n      ‫بينــة أجــاب قائــا‪ :‬بينتــي إقــرار املدعــى عليــه بالكفالــة وأبــرز ورقــة‬\n      ‫وجــرى اطالعنــا عليهــا وهــذا نصهــا‪( :‬كفالــة غــرم وأداء‪ ،‬أقــر أنــا‪/‬‬\n      ‫‪.......‬بصفتــي الشــخصية ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم‬\n      ‫‪.......‬بأننــي أكفــل وأضمــن الســيد‪....... /‬كفالــة غــرم وأداء يف ســداد‬\n      ‫مبلــغ األربعــة ماليــن ريــال ســعودي املترتبــة بذمتــه‪ ،‬للســيد‪،....... /‬‬\n      ‫مبوجــب احلكــم الصــادر مــن احملكمــة العامــة بجــدة برقــم‬\n      ‫(‪ )3/200/334‬وتاريــخ ‪1429/10/15‬ه ـ ‪ ،‬وكذلــك ســداد مبلــغ‬\n      ‫الســتمائة ألــف ريــال ســعودي املترتبــة بذمــة الســيد‪....... /‬احملامــي‪/‬‬\n      ‫‪ ،.......‬كأتعــاب محامــاة‪ ،‬وألتــزم وأتعهــد وأضمن ســداد املبالغ احملددة‬\n      ‫أعــاه ملســتحقيها املذكوريــن مــن أموالــي اخلاصــة يف حالــة تخلــف‬\n      ‫الســيد‪....... /‬املذكــور عــن ســدادها خــال مــدة أقصاهــا (‪ 100‬يــوم)‬\n      ‫مائــة يــوم مــن تاريــخ هــذا اإلقــرار‪ .‬هــذا إقــرار منــي بذلــك‪ ،‬وبرضائــي‬\n      ‫التــام‪ ،‬وأنــا بكامــل األهليــة املعتبــرة شــرع ًا ونظامـاً‪ ،‬وقــد أذنت لشــهود‬\n      ‫احلــال بالشــهادة واهلل خيــر الشــاهدين‪ ،‬املقــر مبــا فيــه‪( ....... :‬التـوقي ــع)‬\n      ‫التاريــخ‪2010/12/29 :‬م‪ ،‬شــاهد (‪( ،....... )1‬التوقيــع)‪ ،‬التاريــخ‬\n      ‫‪2010/10/29‬م شــاهد (‪(....... )2‬التوقيــع) التاريــخ ‪2010/12/29‬م)‪ .‬ا‪.‬‬\n      ‫ه ـ وبســؤال املدعــي وكالــة عــن زيــادة بينــة أحضــر للشــهادة وأدائهــا‪:‬‬\n      ‫‪.......‬وشــهد قائــا‪( :‬أشــهد هلل أن املدعــى عليــه‪....... :‬قــد كفــل املشــتري‬\n      ‫‪ .......‬كفالــة غــرم وأداء يف مبلــغ قــدره‪ :‬أربعــة ماليــن ريــال تســلم‬\n\n\n‫‪269‬‬\n\f‫للمدعــو‪ ......... :‬وكفــل املشــتري أيضــا كفالــة غــرم وأداء يف مبلــغ‬\n‫قــدره‪ :‬ســت مئــة ألــف ريــال تســلم للمدعــي‪ .......‬ووقعنــا ورقــة الكفالــة‬\n‫املرصــودة أعــاه)‪ ،‬هكــذا شــهد‪ .‬وبســؤال املدعــي وكالــة عــن زيــادة‬\n‫بينــة أحضــر للشــهادة وادائهــا‪ ،....... :‬وشــهد قائــا‪( :‬أشــهد هلل أن‬\n‫املدعــو‪....... :‬بــاع عقــار لــه يف جــدة علــى شــخص اســمه‪....... :‬وســدد‬\n‫املشــتري جــزء مــن القيمــة وبقــي عليــه أربعــة ماليــن ريــال وقــد ترافــع‬\n‫املدعــي عــن البائــع يف مطالبــة املشــتري بباقــي الثمــن وصــدر حكــم‬\n‫يلــزم املشــتري بتســديد باقــي الثمــن وقــدره‪ :‬أربعــة ماليــن ريــال‪ ،‬وقــد‬\n‫طلــب املشــتري مهلــة مــن البائــع لتســديد باقــي ثمــن املبيــع وقــدره‪ :‬أربعــة‬\n‫ماليــن ريــال وكــذا تســديد أتعــاب موكلــه باملرافعــة يف هــذه القضيــة‬\n‫وقدرهــا‪ :‬ســت مئــة ألــف ريــال فتــم االتفــاق علــى ذلــك ووقــع علــى عقــد‬\n‫بذلــك وهــو العقــد املرصــود اعــاه‪ ،‬وأشــهد هلل أن املدعــى عليــه‪....... :‬‬\n‫قــد كفــل املشــتري كفالــة غــرم وأداء يف ســداد باقــي ثمــن املبيــع‬\n‫واتعــاب احملامــاة وقدرهــا‪ :‬ســت مئــة ألــف ريــال ووقــع إقــرارا بذلــك‬\n‫رصــد أعــاه)‪ ،‬هكــذا شــهد‪ .‬وجــرى تزكية الشــهود يف ضبط القضية‬\n‫حســب األصــول الشــرعية‪ .‬فبنــاء علــى مــا ســلف‪ ،‬وألن املدعــى عليــه قــد‬\n‫تخ ّلــف عــن احلضــور مــع تبلــغ وكيلــه مبوعــد هــذه اجللســة‪ ،‬واســتالمه‬\n‫لصحيفــة الدعــوى وإفهامــه باجلــواب عليهــا‪ ،‬وحيــث إن غيابــه وعــدم‬\n‫تقــدمي جوابــه ودفاعــه ‪ -‬بعــد علمــه بالدعــوى ومضمونهــا وموعــد اجللســة‬\n‫دون عــذر ‪ -‬يعـ ّـد نكــو ًال عــن اجلــواب‪ ،‬والنــاكل يقضــى عليــه‪ ،‬قــال‬\n‫صاحــب شــرح املنتهــى‪( :‬وإن ســكت مدعــى عليــه) بــأن لم يقــر بالدعوى‬\n‫ولــم ينكرهــا (أو قــال) املدعــى عليــه‪( :‬ال أقــر وال أنكــر أو) قــال‪( :‬ال‬\n‫أعلــم قــدر حقــه وال بينــة) ملــدع بدعــواه ‪ ( ،‬قــال احلاكــم ) ملدعــى عليــه‪:‬‬\n\n\n                                                                                       ‫‪270‬‬\n\f      ‫(إن أجبــت وإال جعلتــك نــاكال وقضيــت عليــك) بالنكــول ‪ .). .‬ا‪.‬ه ـ ويف‬\n      ‫اإلنصــاف‪( :‬قولــه‪( :‬وإن ســكت املدعــى عليــه ‪ ،‬فلــم يقــر ولــم ينكــر‪،‬‬\n      ‫ال وقضيــت عليــك‪،‬‬     ‫قــال لــه القاضــي‪ :‬إن أجبــت ‪ ،‬وإال جعلتــك نــاك ً‬\n      ‫وهــو املذهــب)‪ .‬ا‪ .‬ه ـ وألن امتنــاع املدعــى عليــه عــن احلضــور يعـ ّـد إضــرار‬\n      ‫باملدعــي والضــرر يــزال؛ لقــول النبـ ّـي ‪ -‬صلــى اهلل عليــه وسـلّم‪( :‬ال ضــرر‬\n      ‫وال ضــرار) رواه اإلمــام أحمــد‪ ،‬ومبــا أن للحاكــم واليــة علــى مــال‬\n      ‫الغائــب ويجــوز احلكــم عليــه وعلــى املســتتر واملمتنــع ولــو كان يف البلــد‬\n      ‫[ينظــر‪ :‬الفــروع ‪ ،268/11‬اإلنصــاف ‪ ،249/11‬كشــاف القنــاع‬\n      ‫‪ ،]25/4‬وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n      ‫الشــرعية ولوائحــه التنفيذيــة‪ ،‬وبنــاء علــى عقــد االتفــاق املبرم بــن ‪.........‬‬\n      ‫و ‪ .........‬وبنــاء علــى ورقــة كفالــة املدعــى عليــه للمشــتري املرصــودة‬\n      ‫أن املمتنــع عــن احلضور ُتســمع‬   ‫أعــاه ‪ ،‬وبنــاء علــى شــهادة الشــهود‪ ،‬ومبــا َّ‬\n      ‫ويقضــى بهــا‪ ،‬قــال صاحـ ُـب حتفــة احملتــاج يف شــرح املنهــاج‪:‬‬     ‫البينــة ُ‬\n                                                                                   ‫عليــه ّ‬\n      ‫(وإال لتواريــه أو تعــززه أي‪ :‬تغلبــه وقــد ثبــت ذلــك عنــد القاضــي فتســمع‬\n      ‫البينــة ويحكــم بغيــر حضــوره مــن غيــر ميــن لالســتظهار علــى املنقــول‬      ‫ّ‬\n      ‫املعتمــد تغليظـ ًا عليــه‪ ،‬وإال المتنــع ال َّنــاس ك ّلهــم)‪ ،‬وألن املشــتري ‪.......‬‬\n      ‫تســبب يف اللــدد واملماطلــة يف أداء احلــق للبائــع ‪ ،..........‬ممــا كلــف‬\n      ‫صاحــب احلــق مطالبتــه وتكليفــه أتعــاب احملامــاة‪ ،‬ومبــا أن املشــتري‬\n      ‫التــزم بتســديد هــذه األجــرة وقدرهــا‪ :‬ســت مئــة ألــف ريــال للمدعــي ومبــا‬\n      ‫أن املدعــى عليــه قــد ضمنهــا عــن املشــتري‪ ،‬وألنــه يحــق لصاحــب احلــق‬\n      ‫مطالبــة مــن شــاء مــن الضامــن أو املضمــون عنــه‪ ،‬لذلــك كلــه فقــد‬\n      ‫أمــرت املدعــى عليــه‪...... :‬أن يســلم للمدعــي أصالــة‪...... :‬مبلغــا قــدره‪:‬‬\n      ‫ســت مئــة ألــف ريــال‪ ،‬وبذلــك قضيــت‪ .‬وبإعــان احلكــم قــرر املدعــي‬\n\n\n‫‪271‬‬\n\f‫قناعتــه بــه‪ ،‬أمــا املدعــى عليــه فســوف يبلــغ باحلكــم ولــه االعتــراض‬\n‫بطلــب االســتئناف خــال ثالثــن يومـ ًا اعتبــار ًا مــن تاريــخ تبليغــه بنســخة‬\n‫احلكــم‪ ،‬وإذا تأخــر عــن هــذه املـ ّـدة ـ مــع تبلغــه لشــخصه بنســخة احلكــم‬\n‫ـ ســقط حقــه يف االعتــراض بطلــب االســتئناف واكتســب احلكــم‬\n‫القطعيــة‪ ،‬وإذا تب َّلــغ لغيــر شــخصه ولــم يقـ ِّـدم اعتراضــه رفــع احلكــم‬ ‫ّ‬\n‫لالســتئناف مــن دون اعتــراض‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل وســلم علــى‬\n        ‫نبينا محمد وعلى آله وصحبه وسلّم‪ .‬حرر يف‪1434/11/12 :‬هـ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ويف يــوم الثالثــاء املوافــق‪1434/12/24 :‬ه ـ‬\n‫وقــد قـ ّـدم املدعــى عليــه وكالــة‪...... :‬الئحتــه االعتراضيــة ـ وهــي مكونة‬\n‫مــن أربــع ورقــات مطبوعــة ـ ومقيــدة يف احملكمــة برقــم‪342788049 :‬‬\n‫يف‪1434/12/16 :‬ه ـ ثــم جــرى االطــاع علــى أوراق املعاملــة فوجدنــا‬\n‫أن مقـ ّـدم االعتــراض وكيــا عــن‪...... :‬مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة شــمال جــدة رقــم‪ 95667 :‬يف‪1430/11/07 :‬ه ـ‬\n‫واملخــول لــه فيهــا حــق القناعــة باألحــكام واالعتــراض عليهــا واإلقــرار‬\n‫واإلنــكار والصلــح‪ .‬ا‪ .‬ه ـ وبقــراءة الالئحــة االعتراضيــة وتأملهــا وجدنــا‬\n‫ـخصية‬\n   ‫ّ‬    ‫أن املدعــي‪ ... :‬ليــس لــه املطالبة بصفته الشـ‬    ‫أن أبــرز مــا أثيــر فيهــا ّ‬\n‫وإمنــا املبلــغ املدعــى بــه لشــركة ‪...... ......‬للمحامــاة‪ .‬ا‪ .‬ه ـ واجلــواب علــى‬\n‫ذلــك أن الكفالــة التــي صــدرت مــن املدعــى عليــه كانــت للمدعــي‬\n‫ـخصية‪ ،‬وعلــى فــرض التســليم بــأن املبلــغ محــل الدعــوى‬      ‫ّ‬       ‫بصفتــه الشـ‬\n‫لشــركة ‪......‬للمحامــاة فإنــه قــد جــرى اطالعنــا علــى عقــد تأســيس‬\n‫الشــركة ـ املرفــق بــأوراق املعاملــة ـ فوجدنــاه ينــص علــى‪( :‬يتولــى إدارة‬\n‫الشــركة كال الشــريكني ولــكل واحــد منهــا مجتمعــن أو منفرديــن‬\n‫الصالحيــات والســلطات التاليــة ‪3 . .‬ـ متثيــل الشــركة يف جميــع أنــواع‬\n\n\n                                                                                            ‫‪272‬‬\n\f      ‫الطلبــات واالســتدعاءات والشــكاوى والدعــاوي التــي تقــام منهــا أو‬\n      ‫ضدهــا ‪ . .‬واملرافعــة واملدافعــة واملطالبــة ‪ . .‬واإلقــرار واإلنــكار والصلــح‬\n      ‫‪5 . .‬ـ احلــق يف حتديــد أتعــاب وحقــوق الشــركة والتفــاوض عليهــا مــع‬\n      ‫العمــاء وإبــرام العقــود معهــم والتوقيــع عليهــا باســم الشــركة واحلــق‬\n      ‫يف اســتالم وقبــض كافــة حقــوق الشــركة عينيــة كانــت أو ماليــة‬\n      ‫نقديــة كانــت أو مبوجــب شــيكات)‪ .‬ا‪ .‬ه ـ لذلــك كلــه لــم أجــد يف‬\n      ‫الئحــة املدعــى عليــه وكالــة االعتراضيــة مــا يؤثــر علــى مــا حكمــت بــه‬\n      ‫وأجريتــه‪ .‬وللبيــان جــرى إثباتــه‪ ،‬وأمــرت ببعــث كافــة أوراق املعاملــة‬\n      ‫حملكمــة االســتئناف لتدقيــق احلكــم حســب التعليمــات‪ .‬وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم‪ .‬حــرر يف‪1434/12/24 :‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 34/874869‬وتاريــخ‬\n      ‫‪1435/1/10‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪......‬باحملكمــة العامــة مبحافظــة جــدة برقــم ‪ 34359043‬وتاريــخ‬\n      ‫‪1434/11/12‬ه ـ ‪ ،‬املتضمــن دعــوى ‪ ......‬ضــد ‪ ......‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                     ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪273‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":261,"source_page_end":273,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"95fb60a1178fca750215dda05b35244158e1877c2c303dea31a3b3f8f5430cc4","normalized_text_hash":"e37cedef6701d5528d7a08f523ad049101b14f00c6e27ddf7c7e5e3bc23fdc76","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p261-34359043"},{"id":"aaca2f84-8b31-59b7-b2b3-bed0feb919c2","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة غرم -مطالبة الكفيل بسداد قرض مالي عن مكفوله - إثبات بالشاهد واليمن -عدم حضور املدعى عليه رغم التبليغ -النكول لعدم احلضور -ثبوت الدعوى -احلكم حضوري ا بإلزام املدعى عليه بسداد املبلغ املدعى به للمدعي .","document_number":"34195348","case_number":"34116743","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"كفالة غرم -مطالبة الكفيل بسداد قرض مالي عن مكفوله - إثبات بالشاهد واليمن -عدم حضور املدعى عليه رغم التبليغ -النكول لعدم احلضور -ثبوت الدعوى -احلكم حضوري ا بإلزام املدعى عليه بسداد املبلغ املدعى به للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/22 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34195348 :‬‬\n                   ‫َر ْق ُم الدعوى‪34116743 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34256778‬تاريخه ‪1434/7/2:‬هـ‬\n\n\n‫كفالــة غــرم ‪ -‬مطالبــة الكفيــل بســداد قــرض مالــي عــن مكفولــه ‪-‬‬\n‫إثبــات بالشــاهد واليمــن ‪ -‬عــدم حضــور املدعــى عليــه رغــم التبليــغ‬\n‫‪ -‬النكــول لعــدم احلضــور ‪ -‬ثبــوت الدعــوى ‪ -‬احلكــم حضوري ـ ًا بإلــزام‬\n                       ‫املدعــى عليــه بســداد املبلــغ املدعــى بــه للمدعــي ‪.‬‬\n\n\n\n\n       ‫‪( -1‬أن النبي صلى اهلل عليه وسلم قضى باليمني مع الشاهد)‪.‬‬\n             ‫‪ -2‬قول النبي صلى اهلل عليه وسلم‪( :‬ال ضرر وال ضرار)‪.‬‬\n                          ‫‪ -3‬اليمني تشرع يف جانب أقوى املتداعيني‪.‬‬\n     ‫‪ -4‬املادة (‪ )1/55‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن طرفــا ثالثــا كفــل لديــه أحــد األشــخاص (ذكــر‬\n‫اســمهما يف الدعــوى) كفالــة غرميــة يف ســداد مبلــغ مالــي اقترضــه منــه‬\n‫ثــم ملــا طالــب املدعــي الطــرف الثالــث بســداد مبلــغ القــرض الــذي حــل‬\n‫علــى مكفولــه حضــر إليــه املدعــى عليــه وقــام بكفالتــه لديــه كفالــة‬\n‫غرميــة ‪ ،‬وقــد حــل ذلــك املبلــغ ولــم يســدد لــه املقتــرض وال كفيلــه وال‬\n‫املدعــى عليــه شــيئ ًا منــه ‪ ،‬لــذا طلــب إلــزام املدعــى عليــه بســداد املبلــغ‬\n‫املدعــى بــه لقــاء كفالتــه الغرميــة للطــرف الثالــث ‪ ،‬املدعــى عليــه تبلــغ‬\n\n                                                                                        ‫‪274‬‬\n\f      ‫لشــخصه ولــم يحضــر وهــذا يعــد نكــو ًال عــن اجلــواب علــى الدعــوى‬\n      ‫وقــد أقــام املدعــي بعــض البينــة علــى دعــواه وهــي شــهادة الشــاهد‬\n      ‫املعدلــة شــرع ًا وأدى اليمــن املكملــة طبــق مــا طلــب منــه وقــد قضــى‬\n      ‫النبــي صلــى اهلل عليــه وســلم باليمــن مــع الشــاهد ‪ ،‬قضــت احملكمــة‬\n      ‫حضوري ـ ًا بإلــزام املدعــى عليــه بســداد املبلــغ املدعــى بــه حــا ًال للمدعــي‬\n      ‫‪ ،‬عــارض املدعــى عليــه علــى احلكــم بعــد تبلغــه بــه ‪ ،‬قــررت محكمــة‬\n                                                 ‫االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n      ‫‪ ...‬القاضــي باحملكمــة العامــة باملدينــة املنــورة ففــي هــذا اليــوم األربعــاء‬\n      ‫‪1434/3/25‬ه ـ ويف متــام الســاعة احلاديــة عشــر صباح ـ ًا فتحــت اجللســة‬\n      ‫األولــى بنــاء علــى املعاملــة املقيــدة يف هــذه احملكمــة برقــم ‪34615294‬‬\n      ‫يف ‪1434/3/10‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيس برقم ‪34116743‬‬\n      ‫يف ‪1434/3/10‬ه ـ مبوجبــه حضــر املواطــن يحمــل الهويــة الوطنيــة رقــم‬\n      ‫‪ ...‬ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه رقــم ‪ ...‬تبلغــه مبوعــد‬\n      ‫هــذه اجللســة والتــي حــدد لهــا يف متام الســاعة احلادية عشــر موعد ًا لســماع‬\n      ‫الدعــوى وقــد مت تبليغــه لشــخصه مــن قبــل املوظــف يف هــذه احملكمــة‬\n      ‫حســب إفــادة رئيــس قســم محضــري اخلصــوم يف هــذه احملكمــة شــرح ًا‬\n      ‫علــى ورقــة التبليــغ املؤرخــة يف ‪1434/3/10‬ه ـ ونظــر ًا ملــا نصــت عليــه‬\n      ‫املــادة اخلامســة واخلمســون مــن نظــام املرافعــات الشــرعية فقــد أمــرت‬\n      ‫برفــع اجللســة إلــى يــوم الســبت املوافــق ‪1434/4/13‬ه الســاعة الثامنــة‬\n      ‫صباح ـ ًا ‪ .‬هــذا ويف يــوم االثنــن ‪1434/04/22‬ه ـ ويف متــام الســاعة‬\n\n‫‪275‬‬\n\f‫الثامنــة والنصــف صباح ـ ًا فتحــت اجللســة الثالثــة وفيهــا حضــر املدعــي‬\n‫ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه يف موعــد هذه اجللســة والتي‬\n‫حــدد لهــا يف متــام الســاعة الثامنــة صباحـ ًا موعــد ًا لســماع الدعــوى وقــد‬\n‫وردنــا إفــادة رئيــس قســم محضــري اخلصــوم يف هــذه احملكمــة شــرح ًا‬\n‫علــى ورقــة التبليــغ املؤرخــة يف ‪1434/04/13‬ه ـ أنــه مت االنتقــال إلــى‬\n‫املذكــور‪ -‬املدعــى عليــه عــدة مــرات وأفــاد مديــر الفــرع أن املذكــور‬\n‫يف إجــازة ورفــض اإلفــادة علــى اخلطــاب ومت االنتقــال عــدة مــرات وعليــه‬\n‫قــررت ســماع الدعــوى غيابيـ ًا ‪ ،‬هــذا وادعــى املدعــي علــى املواطن يحمل‬\n‫ا يف حتريــر دعــواه عليــه ‪ :‬قبــل حوالــي خمــس‬         ‫الســجل املدنــي رقــم قائـ ً‬\n‫ســنوات أقرضــت املقيــم ميانــي اجلنســية مبلــغ وقــدره ثالثــة وعشــرون‬\n‫ألــف ريــال علــى أن يســدد لــي هــذا املبلــغ بتاريــخ ‪1429/12/29‬ه ـ وقــد‬\n‫حــل املبلــغ ولــم يســددني املقيــم ريــا ًال واحــد ًا مــن هــذا املبلــغ وقــد كفــل‬\n‫هــذا املقيــم املواطــن كفالــة غراميــة وملــا أردت أن أشــتكي الكفيــل‬\n‫طلــب منــي أن ال أشــتكي وســوف يحضــر لــي موظــف يكفلــه كفالــة‬\n‫غراميــة ‪ ،‬وبالفعــل أحضــر لــي بتاريــخ ‪1433/07/14‬ه ـ املدعــى عليــه‬\n‫وكفــل املدعــى عليــه املواطــن علــى املبلــغ املدعــى بــه وقــدره ثالثــة‬\n‫وعشــرون ألــف ريــال علــى أن يســدد لــي املبلــغ بتاريــخ ‪1434/01/29‬ه ـ‬\n‫ولــم يســددني األخ وال املدعــى عليــه شــيئ ًا مــن هــذا املبلــغ حتــى تاريــخ‬\n‫هــذا اليــوم ‪ ،‬لــذا أطلــب إثبــات ذلــك وإلــزام املدعــى عليــه بســداد املبلــغ‬\n‫املدعــى بــه وقــدره ثالثــة وعشــرون ألــف ريــال حــا ًال لــي لقــاء كفالتــه‬\n‫الغرميــة للمواطــن‪ .‬هــذه دعــواي ‪ .‬ثــم جــرى منــا ســؤال املدعــي هــل لديــه‬\n‫ا ‪ :‬نعــم ‪ .‬هــذا ثــم أحضــر معــه‬    ‫بينــة علــى هــذه الدعــوى فأجــاب قائ ـ ً‬\n‫املواطــن ‪ ....‬يحمــل الهويــة الوطنيــة رقــم ‪ ...‬مــن مواليــد ‪1388/7/10‬ه ـ‬\n\n\n                                                                                            ‫‪276‬‬\n\f      ‫املهنــة متســبب ‪ ،‬ويســكن يف مخطــط األميــر نايــف باملدينــة املنــورة‬\n      ‫عالقتــه باملدعــي صداقــة وليــس لــه عالقــة باملدعــى عليــه وطلــب‬\n      ‫ا ‪ :‬أشــهد هلل تعالــى‬       ‫ســماع مــا لديــه ‪ ،‬وبســؤاله عمــا لديــه شــهد قائ ـ ً‬\n      ‫بــأن املدعــى عليــه كفــل املواطــن كفالــة غرميــة مببلــغ وقــدره ثالثــة‬\n      ‫وعشــرون ألــف ريــال ‪ ،‬وقــد ســمعت املدعــى عليــه وهــو يقــول للمدعــي‬\n      ‫إذا لــم يســددك املبلــغ الــذي بذمــة وقــدره ثالثــة وعشــرون ألــف ريــال‬\n      ‫بتاريــخ ‪1434/01/29‬ه ـ فأنــا أكفلــه يف تســديد املبلــغ كفالــة غرميــة‬\n      ‫وأشــهد هلل تعالــى بــأن املدعــى عليــه لــم يســدد املدعــي ريــا ًال واحــد ًا مــن‬\n      ‫املبلــغ املدعــى بــه واهلل علــى مــا أقــول شــهيد ‪ .‬هكــذا شــهد ‪ .‬ثــم أحضــر‬\n      ‫ال مــن املواطــن يحمــل الهويــة الوطنيــة رقــم ‪ ....‬واملواطــن‬   ‫املدعــي معــه ك ً‬\n      ‫يحمــل الهويــة الوطنيــة رقــم وبســؤالهما عمــا لديهمــا شــهد كل واحــد‬\n      ‫ا ‪ :‬أشــهد هلل تعالــى بــأن الشــاهد عــدل ثقــة مرضــي الشــهادة‬         ‫منهمــا قائـ ً‬\n      ‫لنــا وعلينــا ‪ .‬هكــذا شــهدا ‪ .‬ثــم جــرى منــا ســؤال املدعــي هــل لديــه زيــادة‬\n      ‫ا ‪ :‬ال ليــس لــدي ســوى هــذا الشــاهد ‪ .‬هكــذا أجــاب‪.‬‬           ‫بينــة فأجــاب قائـ ً‬\n      ‫ثــم جــرى منــا عــرض ميــن الشــرعية علــى املدعــي فاســتعد بأدائهــا ‪،‬‬\n      ‫وجــرى منــا تخويفــه بــاهلل ســبحانه وتعالــى مــن اليمــن الغمــوس فأصــر‬\n      ‫ا ‪ :‬واهلل العظيــم‬      ‫علــى أدائهــا ثــم أذنــت لــه بــأداء اليمــن فحلــف قائ ـ ً‬\n      ‫الــذي ال إلــه إال هــو احلــي القيــوم عالــم الغيــب والشــهادة فاطــر الســموات‬\n      ‫واألرض بــأن لــي يف ذمــة املدعــى عليــه مبلــغ وقــدره ثالثــة وعشــرون‬\n      ‫ألــف ريــال مقابــل كفالتــه للمواطــن وأن املدعــى عليــه ومكفولــه لــم‬\n      ‫يســددوني مــن هــذا املبلــغ املدعــى بــه ريــا ًال واحــد ًا وأن أجــل القــرض قــد‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واالطــاع علــى‬     ‫حــل ‪ .‬هكــذا حلــف ‪ .‬فبنـ ً‬\n      ‫أوراق املعاملــة ومبــا أن املدعــى عليــه قــد تبلــغ لشــخصه يف موعــد اجللســة‬\n\n\n‫‪277‬‬\n\f‫األولــى ‪ ،‬ولــم يحضــر يف اجللســة الثانيــة وتعــذر تبليغــه مــن قبــل رئيســه‬\n‫يف العمــل ‪ ،‬ومبــا أن املدعــى عليــه لــم يحضــر يف اجللســة األولــى ولــم‬\n‫يقــدم عــذر ًا لعــدم حضــوره وهــذا يعــد نكــو ًال عــن اجلــواب علــى الدعــوى‬\n‫والنــاكل يقضــى عليــه بالنكــول ومبــا أن املدعــي قــد تضــرر مــن عــدم‬\n‫حضــور املدعــى عليــه وطلــب منــا ســماع دعــواه ضــد املذكــور أعــاه‬\n‫ومبــا أن الشــريعة جــاءت برفــع الضــرر حلديــث (ال ضــرر وال ضــرار)‬\n‫ومبــا أن املدعــي قــد أقــام بعــض البينــة علــى دعــواه وهــي شــهادة الشــاهد‬\n‫املعدلــة شــرع ًا ومبــا أن اليمــن تشــرع يف جانــب أقــوى املتداعيــن وملــا‬\n‫روي عــن بــن عبــاس رضــي اهلل عنهمــا (أن النبــي صلــى اهلل عليــه وســلم‬\n‫قضــى باليمــن مــع الشــاهد) ونظــر ًا ملــا نصــت املــادة اخلامســة واخلمســون‬\n‫يف الالئحــة األولــى مــن نظــام املرافعــات الشــرعية فقــد ألزمــت املدعــى‬\n‫عليــه بســداد املبلــغ املدعــى بــه وقــدره ثالثــة وعشــرون ألــف ريــال حــا ًال‬\n‫للمدعــي ‪ .‬هــذا مــا ظهــر لــي وبــه حكمــت ‪ .‬وهــذا احلكــم يعــد يف حــق‬\n‫املدعــى عليــه حضوري ـ ًا وقــررت بعــث نســخة مــن احلكــم بعــد تســجيله‬\n‫للمدعــى عليــه ليقــدم اعتراضــه خــال املــدة املقــررة نظامـ ًا وهــي ثالثــون‬\n‫يوم ـ ًا مــن تاريــخ التبليــغ وأنــه إذا مضــت مــدة االعتــراض ولــم يقــدم‬\n‫اعتراضــه فــإن احلكــم يكتســب القطعيــة وبــه اختتمــت اجللســة يف متــام‬\n‫الســاعة الثامنــة والنصــف ‪ .‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                           ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/22‬ه ـ ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي هــذا‬\n‫اليــوم الســبت ‪1434/6/17‬ه ـ جــرى منــي االطــاع علــى الالئحــة‬\n‫االعتراضيــة املقدمــة مــن املدعــى عليــه واملكونــة مــن صفحتــن ولــم‬\n‫أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه و للمعلوميــة جــرى حتريــره‬\n\n\n                                                                                       ‫‪278‬‬\n\f      ‫حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر‬\n                                                               ‫يف ‪1434/6/17‬هــ‪.‬‬\n      ‫ويف هــذا اليــوم الثالثــاء املوافــق ‪1434/08/09‬ه ـ افتتحــت اجللســة وقــد‬\n      ‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة بخطابهــم‬\n      ‫رقــم ‪ 34615294‬وتاريــخ ‪1434/07/09‬ه ـ مرفق ـ ًا بــه قــرار الدائــرة‬\n      ‫احلقوقيــة السادســة رقــم ‪ 34256778‬وتاريــخ ‪1434/07/02‬ه ـ املظهــر‬\n      ‫علــى الصــك املتضمــن املوافقــة علــى احلكــم لــذا جــرى إحلاقــه حــرر‬\n      ‫يف ‪1434/08/09‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪279‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":274,"source_page_end":279,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c95f360e9910922dca09917fb2ea389b3b4d67fc69271afee636360882438669","normalized_text_hash":"082ec3da8a5463e3f9391e42b1ed0bf1a2aa91507413c01593476c02ffe09d0f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p274-34195348"},{"id":"60b6f701-083f-58e8-a5ea-e57eb6eac460","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة غرم وأداء -بيع سيارة بأقساط -سداد جزء من الثمن والعجز عن سداد الباقي -مطالبة الكفيل بتسليم باقي ثمن سيارة اشتراها مكفوله -شاهدين ومين على صحة الدعوى -عدم حضور املدعى عليه رغم التبليغ -عدم احلضور نكول عن اجلواب -إلزام املدعى عليه حضوري ا بسداد املبلغ املدعى به .","document_number":"34196212","case_number":"3468167","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة ففي هذا اليوم األحد 1434/3/1ه ويف متام الساعة العاشرة فتحت اجللسة األولى بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/23","year":"1434","subject":"كفالة غرم وأداء -بيع سيارة بأقساط -سداد جزء من الثمن والعجز عن سداد الباقي -مطالبة الكفيل بتسليم باقي ثمن سيارة اشتراها مكفوله -شاهدين ومين على صحة الدعوى -عدم حضور املدعى عليه رغم التبليغ -عدم احلضور نكول عن اجلواب -إلزام املدعى عليه حضوري ا بسداد املبلغ املدعى به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34196212 :‬تاريخه‪1434/4/23 :‬هـ‬\n                    ‫رقم الدعوى‪3468167 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34294971‬تاريخه‪1434/8/13 :‬هـ‬\n\n\n‫كفالــة غــرم وأداء ‪ -‬بيــع ســيارة بأقســاط ‪ -‬ســداد جــزء مــن الثمــن‬\n‫والعجــز عــن ســداد الباقــي ‪ -‬مطالبــة الكفيــل بتســليم باقــي ثمــن‬\n‫ســيارة اشــتراها مكفولــه ‪ -‬شــاهدين وميــن علــى صحــة الدعــوى ‪ -‬عــدم‬\n‫حضــور املدعــى عليــه رغــم التبليــغ ‪ -‬عــدم احلضــور نكــول عــن اجلــواب‬\n             ‫‪ -‬إلــزام املدعــى عليــه حضوري ـ ًا بســداد املبلــغ املدعــى بــه ‪.‬‬\n\n\n\n\n                            ‫‪ .1‬قوله صلى اهلل عليه وسلم (الزعيم غارم) ‪.‬‬\n                     ‫‪ .2‬قوله صلى اهلل عليه وسلم ( ال ضرر وال ضرار ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه‬\n‫بــاع علــى أحــد األشــخاص ســيارة مببلــغ وقــدره ســتون ألــف ريــال علــى‬\n‫أقســاط شــهرية مــع دفعــة مقدمــة قدرهــا ســتة آالف ريال وأمــا بقية املبلغ‬\n‫فيســدد علــى أقســاط شــهرية مقــدار كل قســط ألــف وخمســمائة ريــال‬\n‫اعتبــار ًا مــن ‪1432/2/30‬ه ـ وقــد حــل عليــه حتــى تاريخــه مبلــغ وقــدره‬\n‫تســعة وثالثــون ألــف ريــال ســدد منهــا مبلغ ـ ًا وقــدره ثمانيــة عشــر ألــف‬\n‫ريــال وقــد بقــي يف ذمتــه مبلــغ وقــدره واحــد وعشــرون ألــف ريــال وقــد‬\n‫كفلــه املدعــى عليــه الغائــب عــن مجلــس احلكــم كفالــة غــرم و أداء‬\n\n                                                                                     ‫‪280‬‬\n\f      ‫يف قيمــة الســيارة يطلــب إثبــات ذلــك وإلــزام املدعــى عليــه بدفــع املبلــغ‬\n      ‫احلــال يف ذمــة مكفولــه وقــدره واحــد وعشــرون ألــف ريــال حــا ًال هكــذا‬\n      ‫ادعــى ‪ ،‬ســماع الدعــوى غيابيـ ًا لعــدم حضــور املدعــى عليــه رغــم تبليغــه‬\n      ‫‪ ،‬بينــة املدعــي شــاهدان شــهدا طبــق دعــواه ماعــدا الواصــل والباقــي مــن‬\n      ‫املبلــغ وورقــة إقــرار بكفالــة املدعــى عليــه للمشــتري كفالــة غــرم وأداء‬\n      ‫‪ ،‬حلــف املدعــي ميــن االســتظهار بعــد طلبهــا منــه علــى صحــة دعــواه‬\n      ‫وعلــى عــدم اســتالمه املبلــغ املدعــى بــه ‪ ،‬ملــا تقــدم صــدر احلكــم بإلــزام‬\n      ‫املدعــى عليــه بســداد مبلــغ وقــدره واحــد وعشــرون ألــف ريــال حــا ًال ‪-‬‬\n      ‫يعــد هــذا احلكــم يف حــق املدعــى عليــه حضوريـ ًا بنــاء علــى املــادة‪1/55‬‬\n      ‫مــن نظــام املرافعــات الشــرعية ‪ -‬تبليــغ املدعــى عليــه باحلكــم ‪ ،‬صــدق‬\n      ‫احلكــم مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة االســتئناف مبنطقــة‬\n                                                                     ‫مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ ........‬القاضــي باحملكمــة العامــة باملدينــة املنــورة ففــي هــذا اليــوم‬\n      ‫األحــد ‪1434/3/1‬ه ـ ويف متــام الســاعة العاشــرة فتحــت اجللســة األولــى‬\n      ‫بنــاء علــى املعاملــة املقيــدة يف هــذه احملكمــة برقــم ‪ 34342968‬يف‬\n      ‫‪1434/2/10‬ه ـ واحملالــة إلينــا مــن قبل فضيلة الرئيــس برقم ‪3468167‬‬\n      ‫يف ‪1434/2/10‬ه ـ مبوجبــه حضــر املدعــي ‪ ........‬يحمــل الســجل املدنــي‬\n      ‫رقــم ‪ ........‬ولــم يحضــر املدعــى عليــه و ال مــن ينــوب عنــه رغــم تبلغــه‬\n      ‫لشــخصه مبوعــد هــذه اجللســة والتــي حــدد لهــا الســاعة العاشــرة‬\n      ‫صباح ـ ًا موعــد ًا لســماع الدعــوى وعليــه فقــد أمــرت برفــع اجللســة إلــى‬\n\n‫‪281‬‬\n\f‫يــوم االثنــن ‪1434/4/1‬ه ـ الســاعة العاشــرة صباح ـ ًا ‪ .‬هــذا ويف يــوم‬\n‫اإلثنــن ‪1434/4/1‬ه ـ ويف متــام الســاعة العاشــرة والنصــف صباح ـ ًا‬\n‫فتحــت اجللســة الثانيــة وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه‬\n‫‪ ........‬وال مــن ينــوب عنــه ولــم يقــدم عــذر ًا لعــدم حضــوره وقــد وردنــا‬\n‫إفــادة رئيــس محضــري اخلصــوم يف هــذه احملكمــة شــرح ًا علــى ورقــة‬\n‫التبليــغ املؤرخــة يف ‪1434/3/1‬ه ـ واملتضمــن أنــه لــم يتــم تبليــغ املدعــى‬\n‫عليــه مبوعــد هــذه اجللســة والتــي حــدد لهــا الســاعة العاشــرة صباح ـ ًا‬\n‫موعــد ًا لســماع الدعــوى لعــدم حضــور املدعــي إليهــم وتوضيــح عنــوان‬\n‫املدعــى عليــه هكــذا قــرر وعليــه أمــرت برفــع اجللســة إلــى يــوم الثالثــاء‬\n‫‪1434/4/23‬ه ـ الســاعة الثامنــة والنصــف صباح ـ ًا ‪ .‬هــذا ويف يــوم‬\n‫الثالثــاء املوافــق ‪1434/04/23‬ه ـ ويف متــام الســاعة التاســعة صباح ـ ًا‬\n‫فتحــت اجللســة الثالثــة وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه‬\n‫‪ ........‬وال مــن ينــوب عنــه رغــم تبلغــه مبوعــد هــذه اجللســة والتــي حــدد‬\n‫لهــا يف متــام الســاعة الثامنــة والنصــف موعــد ًا لســماع الدعــوى وقــد‬\n‫مت تبليــغ املدعــى عليــه لشــخصه مــن قبــل محضــر اخلصــوم يف هــذه‬\n‫احملكمــة املوظــف ‪ ........‬حســب إفــادة رئيــس محضــري اخلصــوم يف‬\n‫هــذه احملكمــة شــرط علــى ورقــة التبليــغ املؤرخــة يف ‪1434/04/1‬ه ـ‬\n‫ومبــا أن املدعــى عليــه قــد مت تبليغــه مبوعــد هــذه اجللســة واجللســة قبــل‬\n‫املاضيــة ولــم يحضــر ولــم يقــدم عــذر ًا لعــدم حضــوره لــذا قــررت ســماع‬\n‫الدعــوى غيابي ـ ًا هــذا ثــم أدعــى املدعــي علــى املدعــى عليــه الغائــب عــن‬\n‫ا يف حتريــر دعــواه عليــه إنه بتاريــخ ‪1432/1/19‬هـ‬        ‫مجلــس احلكــم قائـ ً‬\n‫بعــت علــى املقيــم ‪ ........‬باكســتاني اجلنســية ســيارة نــوع فــورد لينكــون‬\n‫واجــن صنــع عــام ‪2005‬م رقــم الهيــكل ‪ ........‬مببلــغ وقــدره ســتون ألــف‬\n\n\n                                                                                     ‫‪282‬‬\n\f      ‫ريــال مؤجــل علــى أقســاط شــهرية مــع دفعــة مقدمــة والدفعــة املقدمــة‬\n      ‫مبلــغ وقــدره ســتة أالف ريــال وأمــا بقيــة املبلــغ فيســدد علــى شــكل‬\n      ‫أقســاط شــهرية قيمــة كل قســط مبلــغ وقــدره ألــف وخمــس مائــة ريــال‬\n      ‫اعتبــار ًا مــن ‪1432/2/30‬ه ـ وقــد حــل عليــه حتــى تاريــخ هــذا اليــوم مبلــغ‬\n      ‫وقــدره تســعة وثالثــون ألــف ريــال ســدد منهــا مبلــغ وقــدره ثمانيــة عشــر‬\n      ‫ألــف ريــال وقــد بقــي يف ذمــه مبلــغ وقــدره واحــد وعشــرون ألــف ريــال لــم‬\n      ‫يســدد منهــا ريــا ًال واحــد ًا حتــى تاريــخ هــذا اليــوم وقــد كفــل املشــتري‬\n      ‫املدعــى عليــه الغائــب عــن مجلــس احلكــم كفالتــه غــرم وأداء يف قيمتــه‬\n      ‫هــذه الســيارة أطلــب إثبــات ذلــك وإلــزام املدعــى عليــه الغائــب عــن‬\n      ‫مجلــس احلكــم بدفــع املبلــغ احلــال يف ذمــة مكفولــه لــي وقــدره واحــد‬\n      ‫وعشــرون ألــف ريــال حــا ًال هــذه دعــواي ثــم جــرى منــا ســؤال املدعــي هــل‬\n      ‫ا نعــم لــدي بنيــة هــذا وقــد أحضــر‬   ‫لديــه بنيــة علــى دعــواه فأجــاب قائ ـ ً‬\n      ‫ال مــن املواطــن ‪ ........‬يحمــل الســجل املدنــي رقــم ‪ ........‬مــن‬    ‫معــه ك ً‬\n      ‫مواليــد ‪1402/4/17‬ه ـ ويعمــل معلــم يف مدرســة ‪ ........‬يف املدينــة املنــورة‬\n      ‫ويســكن يف حــي ‪ ........‬باملدينــة املنــورة ليــس لــه عالقــة باملدعــي وال‬\n      ‫املدعى عليه واملقيم ‪ ........‬باكستاني اجلنسية مبوجب رخصه اإلقامة‬\n      ‫رقــم ‪ ........‬جــوازات مكــة املكرمــة يعمــل ســائق خــاص للمواطــن ‪........‬‬\n      ‫وتســكن يف ‪ ........‬الشــرقية باملدينــة املنــورة مــن مواليــد ‪1395/5/8‬‬\n      ‫ه ـ ويتحــدث العربيــة بطالقــة وبســؤالهما عمــا لديهمــا شــهد كل واحــد‬\n      ‫ا أشــهد هلل تعالــى بأنــه يف شــهر محــرم مــن عــام‬       ‫منهمــا مبفــرده قائ ـ ً‬\n      ‫‪1432‬ه ـ حضرنــا املبايعــة التــي متــت بــن املدعــي وبــن املقيــم ‪ ........‬يف‬\n      ‫ســيارة لينكــون موديــل ‪2005‬م اللــون أبيــض مببلــغ وقــدره ســتون ألــف‬\n      ‫ريــال ودفــع عنــد املبايعــة للمدعــي مبلــغ وقــدره ســته أالف ريــال وبقيــة‬\n\n\n‫‪283‬‬\n\f‫ا علــى أقســاط شــهريه كل قســط مبلــغ وقــدره ألــف‬            ‫املبلــغ كان مؤجـ ً‬\n‫وخمســمائة ريــال وكان مــع املشــتري املدعــى عليــه الغائــب عــن مجلــس‬\n‫احلكــم وقــد كفلــه يف قيمــة الســيارة إذا لــم يســدد املشــتري األقســاط‬\n‫يف حينهــا هــذا مــا لــدي وبــه أشــهد هكــذا شــهد ثــم جــرى منــا ســؤال‬\n‫ا نعــم لــدي بنيــة أخــرى وهــي‬    ‫املدعــي هــل لديــه زيــادة بنيــة فأجــاب قائـ ً‬\n‫العقــد احملــرر مــع املشــتري هــذا ثــم أبــرز لنــا ورقــة محــرره مــن معــرض‬\n‫الشــرق األوســط للســيارات لصاحبه ‪ ........‬برقم ‪ 36‬يف ‪1432/1/19‬هـ‬\n‫ومعنــون باتفاقيــه بيــع ســيارة بالتقســيط هــذا ونــص احلاجــة منــه أقــر أنــا‬\n‫املوقــع اســمي أدنــاه ‪ ........‬بأننــي قــد اشــتريت ســيارة فــورد لينكــون‬\n‫واجــن موديــل ‪2005‬م بنمــرة واســتمارة حــرة رقــم االســتمارة خصوصــي‬\n‫رقــم الهيــكل ‪ ........‬رقــم اللوحــة ‪ ........‬مــن املكــرم ‪ ........‬مببلــغ وقــدره‬\n‫‪ 60.000‬ســتون ألــف ريــال وقــد دفعــت حــال توقيعــي علــى عقــد املبايعــة‬\n‫مبلــغ وقــدره ســتة االف ريــال والباقــي قــدره ‪ 54000‬يقســط علــى ‪1500‬‬\n‫ريــال كل شــهر ابتــداء مــن ‪1432/2/30‬ه ـ أقــر أنــا املوقــع أســمي أدنــاه‬\n‫وبطوعــي واختيــاري وأمــا الشــهود احلاضريــن بــأن أكفــل الســيد ‪........‬‬\n‫غــام كفالــة غــرم وأداء مببلــغ وقــدره ‪ 60.000‬ســتون ألــف ريــال للســيد‬\n‫‪ ........‬ويف حالــة تأخــر عــن الدفــع أو وفاتــه أدفــع عنــه بــدون تأخيــر‬\n‫وال مماطلــه وعليــه أوقــع ا‪.‬ه ـ باســم املدعــى عليــه الغائــب عــن مجلــس‬\n‫ال مــن املواطــن‬ ‫احلكــم ‪ ........‬وتوقيعــه هــذا ثــم أحضــر املدعــي معــه ك ً‬\n‫ع‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬املقيــم‬\n‫‪ ........‬مينــي اجلنســية مبوجــب رخصــة االقامــة رقــم ‪ ........‬وبســؤالهما عمــا‬\n‫لديهمــا شــهدا قائلــن إن هذيــن الشــاهدين وهمــا ‪ ........‬و‪ ........‬عــدول‬\n‫ثقــات مرخصــن الشــهادة لنــا وعلينــا هكــذا شــهدا هــذا ثــم جــرى منــا‬\n\n\n                                                                                          ‫‪284‬‬\n\f      ‫عــرض ميــن االســتظهار علــى املدعــي فأســتعد بأدائهــا ثــم جــرى منــا‬\n      ‫تخويفــه بــاهلل ســبحانه وتعالــى مــن اليمــن الغمــوس فأصــر علــى أدائهــا‬\n      ‫ا واهلل العظيــم الــذي ال إلــه إال‬    ‫ثــم أذنــت لــه بــأداء اليمــن فحلــف قائ ـ ً‬\n      ‫هــو احلــي القيــوم عالــم الغيــب والشــهادة فاطــر الســموات واألرض بــأن‬\n      ‫لــي يف ذمــة املشــتري ‪ ........‬مبلــغ وقــدره واحــد وعشــرون ألــف ريــال‬\n      ‫حالــة يف ذمتــه وأن املدعــى عليــه قــد كفــل هــذا املشــتري كفالــة غــرم‬\n      ‫وأداء يف قيمــة هــذه الســيارة وأننــي لــم أســتلم ريــا ًال واحــد ًا مــن املبلــغ‬\n      ‫احلــال يف ذمــة املشــتري ال مــن املشــتري وال مــن كفيلــه حتــى تاريــخ‬\n      ‫هــذا اليــوم واهلل علــى مــا أقــول شــهيد هكــذا أحلــف فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واالطــاع علــى أوراق املعاملــة ومبــا أن املدعــى عليــه‬\n      ‫قــد تغيــب عــن هــذه اجللســة وعــن اجللســة التــي قبــل املاضيــة رغــم تبلغــه‬\n      ‫مبوعدهمــا لشــخصه حســب إفــادة محضــري اخلصــوم ولــم يقــدم عــذر ًا‬\n      ‫لعــدم حضــوره وهــذا بعــد نكــو ًال عــن اجلــواب علــى الدعــوى والنــاكل‬\n      ‫يقضــى عليــه بالنكــول كمــا قــرر بذلــك العلمــاء ومبــا أن املدعــي قــد‬\n      ‫أقــام البينــة علــى دعــواه وهــي شــهادة الشــاهدين املعدلــة شــرع ًا ونظــرا‬\n      ‫ملــا تضمنــه شــهادة الشــاهدين املدونــة أعــاه ومــا تضمنــه اتفاقيــة لبيــع‬\n      ‫الســيارة بالتقســيط املثــار إليهــا مباليــه ومبــا أن املدعــي قــد أدى ميــن‬\n      ‫االســتظهار علــى إثبــات دعــواه ونظــر ًا ملــا قــرره الفقهــاء مــن ان لــرب املــال‬\n      ‫مطالبــة لضامــن أو املضمــون حلديــث (الزعيــم غــارم ) وحيــث تضــرر‬\n      ‫املدعــي مــن عــدم حضــور املدعــى عليــه وطلــب منــا ســماع دعــواه ضــد‬\n      ‫املذكــور أعــاه وحيــث جــاءت الشــريعة برفــع الضــرر حلديــث ( ال ضــرر‬\n      ‫وال ضــرار ) جلميــع مــا ذكــر فقــرر الزمــه املدعــى عليــه بســداد املبلــغ‬\n      ‫املدعــى بــه وقــدره واحــد وعشــرون ألــف ريــال احلــال يف ذمــة مكفولــه‬\n\n\n‫‪285‬‬\n\f‫حــاال للمدعــي وهــذا احلكــم يعــد يف حــق املدعــى عليــه حضوريـ ًا وفقـ ًا‬\n‫ملــا نصــت عليــه املــادة اخلامســة واخلمســون يف الالئحــة األولــى مــن نظــام‬\n‫املرافعــات الشــرعية وقــررت ببعــث نســخه مــن صــك احلكــم بعــد‬\n‫تســجيله للمدعــى عليــه ليقــدم اعتراضــه خــال املــدة املقــررة نظامــا‬\n‫وهــي ثالثــون يومــا مــن تاريــخ التبليــغ وانــه إذا مضــت مــدة االعتــراض‬\n‫ولــم يقــدم اعتراضــه فــإن احلكــم يكتــب الصفــة القطعيــة وبــه اختتمــت‬\n‫اجللســة يف متــام الســاعة والنصــف صباح ـ ًا وصلــى اهلل وســلم علــى نبينــا‬\n                                           ‫محمــد حــرر يف ‪1434/4/23‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ‪ ........ /‬باحملكمــة العامــة باملدينــة املنــورة واملســجل بعــدد‬\n‫‪34196212‬وتاريــخ ‪1434/4/23‬ه ـ املتضمــن دعــوى ‪ ........‬ي ضــد‬\n‫‪ ........‬واحملكــوم فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة ضبطــه‬\n‫تقــررت املوافقــة علــى احلكــم وعلــى فضيلتــه مراعــاة التنبيــه املرفــق‬\n     ‫باملعاملــة وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪286‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":280,"source_page_end":286,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4ef1c9c894ec332c8dbfb9e829f3246bf3d18f28a66de714b06edddd5a7953a4","normalized_text_hash":"c20e3a68d343b107d389ba3a8a35e8b4f3d9d3eac4c3ad02461ce507fe551fa7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p280-34196212"},{"id":"942c025c-f333-58f7-97d6-c5262734cff5","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة غرم وأداء -بيع بطاقات سوا بأقساط -سداد جزء من الثمن والعجز عن سداد الباقي -مطالبة الكفيل بتسليم باقي ثمن البطاقات التي اشتراها مكفوله -بينة املدعي عقد البيع املذيل بتوقيع الكفيل -شاهد ومين على صحة الدعوى -عدم حضور املدعى عليه رغم التبليغ -إلزام املدعى عليه حضوري ا بسداد املبلغ .","document_number":"34230310","case_number":"34231860","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بدومة اجلندل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/4","year":"1434","subject":"كفالة غرم وأداء -بيع بطاقات سوا بأقساط -سداد جزء من الثمن والعجز عن سداد الباقي -مطالبة الكفيل بتسليم باقي ثمن البطاقات التي اشتراها مكفوله -بينة املدعي عقد البيع املذيل بتوقيع الكفيل -شاهد ومين على صحة الدعوى -عدم حضور املدعى عليه رغم التبليغ -إلزام املدعى عليه حضوري ا بسداد املبلغ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34230310 :‬تاريخه‪1434/6/4 :‬هـ‬\n                         ‫رقم الدعوى‪34231860 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34266923‬تاريخه‪1434/7/12 :‬هـ‬\n\n\n      ‫كفالــة غــرم وأداء ‪ -‬بيــع بطاقــات ســوا بأقســاط ‪ -‬ســداد جــزء مــن‬\n      ‫الثمــن والعجــز عــن ســداد الباقــي ‪ -‬مطالبــة الكفيــل بتســليم باقــي‬\n      ‫ثمــن البطاقــات التــي اشــتراها مكفولــه ‪ -‬بينــة املدعــي عقــد البيــع‬\n      ‫املذيــل بتوقيــع الكفيــل ‪ -‬شــاهد وميــن علــى صحــة الدعــوى ‪ -‬عــدم‬\n      ‫حضــور املدعــى عليــه رغــم التبليــغ ‪ -‬إلــزام املدعــى عليــه حضوري ـ ًا‬\n                                                                  ‫بســداد املبلــغ ‪.‬‬\n\n\n\n\n      ‫‪ .1‬مــا رواه ابــن عبــاس رضــي اهلل عنــه (أن النبــي صلــى اهلل عليــه و ســلم‬\n                                                           ‫قضــى بيمــن وشــاهد)‪.‬‬\n                   ‫‪ .2‬الفقرة األولى من املادة ‪ 55‬من نظام املرافعات الشرعية‪.‬‬\n                                   ‫‪ .3‬املادة (‪ )119‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه‬\n      ‫اشــترى منــه ألف ـ ًا و أربــع و ثمانــن بطاقــة ســوا مببلــغ إجمالــي قــدره‬\n      ‫ثمانيــة عشــر ألــف ريــال مقســطه علــى أقســاط شــهرية كل قســط‬\n      ‫ألــف ريــال وقــد ســلمه املشــتري مــن األقســاط ســتة آالف ريــال وبقــي‬\n      ‫يف ذمتــه مــن األقســاط مبلــغ وقــدره اثنــا عشــر ألــف ريــال وهــي حالــه‬\n\n‫‪287‬‬\n\f‫واملدعــى عليــه كفيــل ضامــن للمشــتري ويطلــب إلــزام املدعــى عليــه‬\n‫بســداد مــا بقــي يف ذمــة املضمــون عنــه وهــو مبلــغ وقــدره اثنــا عشــر‬\n‫ألــف ريــال هكــذا ادعــى ‪ ،‬لــم يحضــر املدعــى عليــه مــع تبلغــه فجــرى‬\n‫ســماع الدعــوى غيابي ـ ًا اســتناد ًا للفقــرة األولــى مــن املــادة ‪ 55‬مــن نظــام‬\n‫املرافعــات الشــرعية ‪ ،‬بينــة املدعــي عقــد البيــع ومذيــل بتوقيــع البائــع‬\n‫املدعــي واملشــتري والكفيــل املدعــى عليــه كمــا أحضــر شــاهد ًا شــهد‬\n‫طبــق دعــواه وعــدل شــرع ًا ‪ ،‬حلــف املدعــي اليمــن بعــد طلبهــا منــه‬\n‫علــى صحــة دعــواه وعلــى كفالــة املدعــى عليــه للمشــتري وعــدم ســداد‬\n‫املشــتري املبلــغ املدعــى بــه ‪ ،‬لشــهادة الشــاهد املعــدل طبــق األصــول‬\n‫الشــرعية ولليمــن املرصــودة بعاليــه وألن النبــي صلــى اهلل عليــه و ســلم‬\n‫قضــى بالشــاهد و اليمــن وحيــث إن لــرب الديــن مطالبــة مــن شــاء مــن‬\n‫الضامــن واملضمــون عنــه واســتنادا للفقــرة األولــى مــن املــادة اخلامســة‬\n‫و اخلمســن مــن نظــام املرافعــات الشــرعية ‪ ،‬ملــا تقــدم صــدر احلكــم‬\n‫حضوريـ ًا علــى املدعــى عليــه بــأن يســلم للمدعــي مبلغـ ُا وقــدره اثنــا عشــر‬\n‫ألــف ريــال وإفهامــه بــأن لــه الرجــوع علــى مكفولــه مبــا يســدد عنــه ‪،‬‬\n‫تبليــغ املدعــى عليــه باحلكــم ‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n                            ‫األولــى مبحكمــة االســتئناف مبنطقــة اجلــوف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪......‬رئيــس احملكمــة العامــة بدومــة‬\n‫اجلنــدل وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 34231860‬وتاريــخ‬\n‫‪1434/05/20‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341226822‬وتاريــخ‬\n‫‪1434/05/20‬ه ـ ففــي يــوم األحــد املوافق‪1434/06/04‬ه ـ افتتحــت‬\n\n                                                                                        ‫‪288‬‬\n\f      ‫اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر ‪......‬ســعودي اجلنســية مبوجــب‬\n      ‫ســجل مدنــي رقــم ‪......‬ولــم يحضــر املدعى عليه ‪......‬وقــد وردنا عن طريق‬\n      ‫الفاكــس مــن بلديــة ‪......‬صــورة مــن خطابنــا رقــم ‪......‬يف ‪1434/5/20‬ه ـ‬\n      ‫وقــد ذيــل فيــه إقــرار املدعــى عليــه باحلضــور وتوقيعــه علــى ورقــة التبليــغ‬\n      ‫وحيــث تبلــغ املدعــى عليه لشــخصه وقررت نظر الدعوى غيابي ًا اســتناد ًا‬\n      ‫للمــادة اخلامســة و اخلمســن مــن نظــام املرافعــات الشــرعية فأفهمــت‬\n      ‫ا أشــترى منــي املدعــو‪...... /‬عــدد‬  ‫املدعــي بتحريــر دعــواه فأدعــى قائ ـ ً‬\n      ‫الــف و أربعــة و ثمانــون بطاقــة ســوا مببلــغ إجمالــي وقــدره ثمانيــة عشــر‬\n      ‫ألــف ريــال مقســطه علــى أقســاط شــهرية كل قســط ألــف ريــال وذلــك‬\n      ‫اعتبــار ًا مــن ‪1432/6/25‬ه ـ وقــد ســلمني املشــتري مــن األقســاط ســتة‬\n      ‫اآلف ريــال وبقــي يف ذمتــه مــن األقســاط مبلــغ وقــدره اثنــا عشــر ألــف‬\n      ‫ريــال وهــي حالــه واملدعــى عليــه كفيــل ضامــن للمشــتري لــذا أطلــب‬\n      ‫إلــزام املدعــى عليــه بســداد مــا بقــي يف ذمــة املضمــون عنــه وهــو مبلــغ‬\n      ‫وقــدره اثنــا عشــر ألــف ريــال هــذه دعــواي وبطلــب البينــة مــن املدعــي‬\n      ‫أبــرز عقــد ًا مؤرخ ـ ًا يف ‪1432/6/11‬ه ـ يتضمــن إتفــاق الطــرف األول‬\n      ‫‪......‬بصفتــه بائع ـ ًأ والطــرف الثانــي ‪......‬بصفتــه مشــتري ًا علــى أن يبيــع‬\n      ‫الطــرف األول للطــرف الثانــي عــدد الــف و أربعــة و ثمانــون بطاقــة ســوا‬\n      ‫مببلــغ إجمالــي وقــدره ثمانيــة عشــر ألــف ريــال مقســطة علــى أقســاط‬\n      ‫شــهرية كل قســط ألــف ريــال وذلــك إعتبــار ًا مــن ‪1432/6/25‬ه ـ وعلــى‬\n      ‫العقــد توقيــع ‪ ......‬بصفتــه بائعـ ًا و ‪......‬بصفتــه مشــتري ًا وبكفالــة املدعــى‬\n      ‫عليــه ‪......‬وبطلــب زيــادة بينــة أحضــر للشــهادة ‪ ......‬مصــري اجلنســية‬\n      ‫يحمــل رخصــة إقامــة للمســلمني رقــم ‪......‬يقيــم يف محافظــة ‪............‬‬\n      ‫ا أشــهد بــاهلل العظيــم‬ ‫املهنــة ســائق خــاص وبســؤاله عمــا لديــة شــهد قائـ ً‬\n\n\n‫‪289‬‬\n\f‫بــأن املدعــو‪...... /‬اشــترى مــن املدعــي هــذا احلاضــر عــدد الــف وأربعــة‬\n‫و ثمانــون بطاقــة ســوا مببلــغ إجمالــي وقــدره ثمانيــة عشــر ألــف ريــال‬\n‫مقســطة علــى أقســاط شــهرية كل قســط ألــف ريــال وذلــك إعتبــار ًا‬\n‫مــن ‪1432/6/25‬ه ـ وقــد ســلم املشــتري مــن األقســاط ســتة اآلف ريــال‬\n‫وبقــي يف ذمتــه مــن األقســاط اثنــا عشــر ألــف ريــال واملدعــى عليــه ج‪......‬‬\n‫كفيــل ضامــن للمشــتري هكــذا شــهد وبســؤاله عــن عالقتــه باملدعــي‬\n‫ا بأنــه ليــس لــي عالقــة بــه ثــم جــرى تعديــل الشــاهد مــن قبــل‬‫أجــاب قائـ ً‬\n‫‪......‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪......‬و ‪............‬ســعودي‬\n‫اجلنســية مبوجــب ســجل مدنــي رقــم ‪......‬حيــث شــهدا بعدالــة الشــاهد‬\n‫وثقتــه وأنــه مرضــي الشــهادة وبعــرض اليمــن علــى املدعــي أســتعد بهــا‬\n‫ا واهلل الــذي ال إلــه إال هــو بــأن املدعــو ‪...... /‬اشــترى منــي‬\n                                                                    ‫ثــم حلــف قائـ ً‬\n‫عــدد الــف و أربعــة و ثمانــون بطاقــة ســوا مببلــغ إجمالــي وقــدره ثمانيــة‬\n‫عشــر ألــف ريــال مقســطة علــى أقســاط شــهرية كل قســط ألــف ريــال‬\n‫وذلــك إعتبــار ًا مــن ‪1432/6/25‬ه ـ وقــد ســلمني املشــتري مــن األقســاط‬\n‫ســتة أالف ريــال وبقــي يف ذمتــه مــن األقســاط مبلــغ وقدره اثنا عشــر ألف‬\n‫ريــال وهــي حالــه واملدعــى عليــه كفيــل ضامــن للمشــتري هكــذا حلــف‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى وحيــث تبلــغ املدعــى عليــه لشــخصه‬      ‫فبنـ ً‬\n‫ولــم يحضــر وحيــث إن الدعــوى تســمع علــى املمتنــع و الغائــب كمــا‬\n‫قــرره أهــل العلــم وحيــث جــرى اإلطــاع علــى العقــد أعــاه ولشــهادة‬\n‫الشــاهد املعــدل طبــق األصــول الشــرعية ولليمــن املرصــودة بعاليــه وألن‬\n‫النبــي صلــى اهلل عليــه و ســلم قضــى بالشــاهد و اليمــن وحيــث إن لــرب‬\n‫الديــن مطالبــة مــن شــاء مــن الضامــن واملضمــون عنــه وإســتناد ًا للفقــرة‬\n‫األولــى مــن املــادة اخلامســة و اخلمســن مــن نظــام املرافعــات الشــرعية‬\n\n\n                                                                                        ‫‪290‬‬\n\f      ‫فقــد حكمــت حضوري ـ ًا علــى املدعــى عليــه بــأن يســلم للمدعــي مبلــغ‬\n      ‫وقــدره اثنــا عشــر ألــف ريــال وإفهامــه بــأن لــه الرجــوع علــى مكفولــه‬\n      ‫مبــا يســدد عنــه وســيتم بعــث نســخه مــن احلكــم للمدعــى عليــه فــإن‬\n      ‫أســتلمها و أعتــرض خــال ثالثــن يومـ ًا و إال ســقط حقــه يف االعتــراض‬\n      ‫واكتســب احلكــم القطعيــة وكان إعــان احلكــم و إبالغــه يــوم األحــد‬\n      ‫املوافــق ‪1434/6/4‬ه ـ واقفلــت اجللســة يف متــام الســاعة احلاديــة عشــر‬\n      ‫و النصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/04‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1434/08/01‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة الواحــدة وفيهــا حضــر املدعــي وقــد وردتنــا‬\n      ‫املعاملــة مــن محكمــة االســتئناف مبنطقــة اجلــوف وبرفقهــا القــرار‬\n      ‫رقــم ‪ 34266923‬يف ‪1434/7/12‬ه ـ واملتضمــن بعــد املقدمــة وبدراســة‬\n      ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ‬\n      ‫مــا يلــي ‪ :‬أوالً‪ :‬ســمع فضيلتــه الدعــوى يف أول جلســة ولــم يحــدد‬\n      ‫جلســة ثانيــة حســبما نصــت علــى ذلــك املــادة (‪ )55‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ‪ .‬ثاني ـاً‪ :‬ذكــر فضيلتــه أن العقــد يحمــل توقيــع املشــتري‬\n      ‫واجلــزم بذلــك مــن اختصــاص اجلهــة املختصــة ( واألن ـسـ ــب أن يقــال‬\n      ‫توقيــع منســوب للمشــتري ) ‪ .‬ثالث ـاً‪ :‬لــم يســتكمل فضيلتــه مــا نصــت‬\n      ‫عليــه املــادة (‪ )119‬مــن نظــام املرافعــات الشــرعية فيمــا يتعلــق بالشــاهد‬\n      ‫ولــم يوضــح هــل الشــاهد يعمــل أجيــر ًا لــدى املدعــي أو حتــت كفالتــه أم‬\n      ‫ال ؟ ولــم يســتوضح فضيلتــه مــن الشــاهد كيــف علــم باملبالــغ الواصلــة‬\n      ‫و املتبقيــة ولــم يتــم إرفــاق صــورة مــن إقامتــه والبــد مــن ذلــك ‪ .‬رابع ـاً‪:‬‬\n      ‫تصحيــح األخطــاء النحويــة و اإلمالئيــة يف الصــك املشــار إليهــا بقلــم‬\n\n\n‫‪291‬‬\n\f‫الرصــاص ‪ .‬فعلــى فضيلتــه مالحظــة مــا ذكــر وإجــراء مــا يلــزم حســب‬\n‫التعليمــات ‪ .‬وعليــه اجيــب أصحــاب الفضيلــة قضــاة االســتئناف بأنــه مــا‬\n‫يتعلــق باملالحظــة األولــى فقــد مت ســماع الدعــوى اســتناد ًا للفقــرة األولــى‬\n‫مــن املــادة اخلامســة و اخلمســن مــن نظــام املرافعــات الشــرعية و اعتبــر‬\n‫احلكــم حضوريـ ًا يف حــق املدعــى عليــه وأمــا مــا يتعلــق باملالحظــة الثانيــة‬\n‫فــإن مــا مت ذكــره بــأن العقــد يحمــل توقيــع املشــتري فقــد ذكــر ذلــك‬\n‫علــى ســبيل النقــل مبــا جــاء يف العقــد املــدون أعــاه وليــس علــى ســبيل‬\n‫اجلــزم ولــذا ُط ِلـ َـب مــن املدعــي زيــادة بينــة وســيتم مالحظــة ذلــك مســتقب ً‬\n‫ال‬\n‫وأمــا مــا يتعلــق باملالحظــة الثالثــة فقــد حضــر يف هــذه اجللســة الشــاهد‬\n‫املدونــة شــهادته بعاليــه وحيــث مت تدويــن محــل إقامــة الشــاهد ومهنتــه‬\n‫ولــم يــدون ســنه فقــد جــرى ســؤال الشــاهد عــن ســنه فأجــاب بأنــه يبلــغ‬\n‫مــن العمــر (‪ 28‬ســنه ) وأنــه ليــس لــه عالقــة باملدعــي وليــس أجيــر ًا يعمــل‬\n‫لديــه و إمنــا يعمــل أجيــر ًا لــدى املدعــو ‪...... /‬وهــو حتــت كفالتــه كمــا‬\n‫جــرى ســؤاله عــن كيفيــة علمــه باملبالــغ الواصلــة و املتبقيــة فأجــاب‬\n‫ا بــأن املبالــغ تســدد عــن طريــق املكتــب وقــد ســلم املشــتري مــن‬        ‫قائ ـ ً‬\n‫األقســاط ســتة اآلف ريــال وبقــي يف ذمتــه مــن األقســاط مبلــغ وقــدره‬\n‫اثنــا عشــر ألــف ريــال وقــد مت االتصــال عليــه عــدة مــرات لتســديد املبلــغ‬\n‫املتبقــي وقــد وعــد بتســديده إال أنــه تخلــف عــن ذلــك علمـ ًا بأننــي أنــا مــن‬\n‫قــام بإبــرام العقــد بــن البائــع و املشــتري وبحضــور الكفيــل املدعــى‬\n‫عليــه أ‪.‬ه ـ هكــذا أجــاب وقــد مت إرفــاق صــورة مــن إقامــة الشــاهد وأمــا‬\n‫مــا يتعلــق باملالحظــة الرابعــة فقــد جــرى إكمــال الــازم حيالهــا وبذلــك‬\n‫متــت اإلجابــة واالســتجابة ملشــائخنا األفاضــل و أمــرت بإحلــاق ذلــك علــى‬\n‫الصــك و ســجله و إعــادة املعاملــة حملكمــة االســتئناف مبنطقــة ‪......‬‬\n\n\n                                                                                          ‫‪292‬‬\n\f      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم ‪ .‬حــرر يف ‪ 1434/08/01‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n      ‫األولــى يف محكمــة االســتئناف مبنطقــة اجلــوف علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة دومــة اجلنــدل الشــيخ ‪/‬‬\n      ‫‪ ......‬برقــم ‪ ......‬وتاريــخ ‪1434/8/2‬ه ـ املقيــدة لــدى هــذه احملكمــة برقــم‬\n      ‫‪ 341907045‬وتاريــخ ‪1434/8/7‬ه ـ املرفــق بهــا الصــك الص ــادر مــن‬\n      ‫فضيل ــته برقــم ‪ 34230310‬وتاريــخ ‪1434/6/4‬هـ ـ املتعلــق بدعــوى‪....../‬‬\n      ‫ضــد‪ ...... /‬يف مطالبــة ماليــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل فيــه ‪ .‬وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي‬\n      ‫ـاء علــى قرارنــا رقــم ‪34266923‬‬        ‫وأحلقــه بالصــك وصــورة ضبطــه بنـ ً‬\n      ‫وتاريــخ ‪1434/7/12‬ه ـ فــأن الدائــرة تقــرر املصادقــة علــى احلكــم بعــد‬\n      ‫األجــراء األخيــر مــع تنبيــه فضيلتــه ‪ -‬وفقــه اهلل ‪ -‬إلــى أنــه أفهــم املدعــى‬\n      ‫عليــه بأنــه لــه حــق الرجــوع إلــى مكفولــة مبــا يســدد عنــه إلــى أن اإلفهــام‬\n      ‫بــأن لــه حــق الرجــوع مطلقـاً‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                           ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪293‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":287,"source_page_end":293,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"249a40f1fb6c430462cf05040476a46dd5cb09707c6993e34c3f5a81ec631996","normalized_text_hash":"6b6124bf9edcce3d1b7c59b34055971d5ad14c3279fca14f71f5cbd1383f5a1a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p287-34230310"},{"id":"f0746355-34eb-53a2-8dc6-f1108925a521","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة غرم وأداء -بيع سيارة واالتفاق على قبض الثمن على دفعتن -العجز عن السداد -مطالبة املدعى عليه (الكفيل) بسداد باقي ثمن سيارة اشتراها مكفولة -عدم حضور املدعى عليه رغم التبليغ -اإلثبات مبوجب كمبياالت ومين االستظهار -إلزام املدعى عليه حضوري ا بسداد املبلغ .","document_number":"34271120","case_number":"33629349","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف القائم بعمل القسم القضائي السابع بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"كفالة غرم وأداء -بيع سيارة واالتفاق على قبض الثمن على دفعتن -العجز عن السداد -مطالبة املدعى عليه (الكفيل) بسداد باقي ثمن سيارة اشتراها مكفولة -عدم حضور املدعى عليه رغم التبليغ -اإلثبات مبوجب كمبياالت ومين االستظهار -إلزام املدعى عليه حضوري ا بسداد املبلغ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34271120 :‬تاريخه‪1434/7/17 :‬هـ‬\n                  ‫رقم الدعوى‪33629349 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34345205‬تاريخه‪1434/10/29 :‬هـ‬\n\n\n‫كفالــة غــرم وأداء ‪ -‬بيــع ســيارة واالتفــاق علــى قبــض الثمــن علــى‬\n‫دفعتــن ‪ -‬العجــز عــن الســداد ‪ -‬مطالبــة املدعــى عليــه (الكفيــل) بســداد‬\n‫باقــي ثمــن ســيارة اشــتراها مكفولــة ‪ -‬عــدم حضــور املدعــى عليــه رغــم‬\n‫التبليــغ ‪ -‬اإلثبــات مبوجــب كمبيــاالت وميــن االســتظهار ‪ -‬إلــزام‬\n                                   ‫املدعــى عليــه حضوري ـ ًا بســداد املبلــغ ‪.‬‬\n\n\n\n\n                    ‫‪ .1‬قوله تعالى (وملن جاء به حمل بعير وأنا به زعيم) ‪.‬‬\n‫‪ .2‬جــاء يف الــكايف البــن قدامــة ‪ 128/6‬مــا نصــه ( فــإن امتنــع اخلصــم‬\n‫مــن احلضــور عنــد احلاكــم حكــم عليــه ألنــه لــو لــم يحكــم عليــه جلعــل‬\n                         ‫االمتنــاع واالســتتار طريقـ ًا لتضييــع احلقــوق ) أ‪.‬ه ـ‬\n‫‪ .3‬جــاء يف معــن احلــكام علــى القضايــا واألحــكام مــا نصــه‪ ( :‬مســألة‬\n‫قــال املــاوردي يف تفســير قولــه تعالــى ( وإذا دعــوا إلــى اهلل ورســوله‬\n‫ليحكــم بينهــم ) اآليــة دليــل علــى أنــه مــن دعــي إلــى حاكــم مــن حــكام‬\n‫املســلمني فعليــه اإلجابــة ويحــرج إن تأخــر وقــد ورد عــن احلســن بــن‬\n‫علــي رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم قــال ( مــن دعــي‬\n‫إلــى حاكــم مــن حــكام املســلمني ولــم يجــب فهــو ظالــم ال حــق لــه ) أ‪.‬ه ـ‬\n           ‫‪ .4‬املادة ‪ 55‬من نظام املرافعات الشرعية ولوائحها التنفيذية ‪.‬‬\n\n\n\n                                                                                     ‫‪294‬‬\n\f      ‫قــام شــخص بكفالــة والــده بشــراء ســيارة مت ســداد جــزء مــن ثمنهــا‬\n      ‫واالتفــاق علــى ســداد باقــي الثمــن علــى دفعتــن‪ ،‬جــاء موعد حلــول الثمن‬\n      ‫ولــم يتــم ســداد املبلــغ‪ ،‬طالــب املدعــي الضامــن بســداد املبلــغ نظــر ًا حللــول‬\n      ‫األجــل وعــدم حضــور املكفــول مجلــس احلكــم رغــم تبليغــه لشــخصه ‪،‬‬\n      ‫ا لصحــة دعــواه كمبيالتــن مســتحقتي الدفــع كمــا حلــف‬              ‫وقــدم دلي ـ ً‬\n      ‫اليمــن علــى صحــة دعــواه ‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع‬\n      ‫املبلــغ للمدعــي وتبليــغ املدعــى عليــه باحلكــم ‪ ،‬متــت املصادقــة علــى‬\n                    ‫احلكــم مــن محكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ففــي‬\n      ‫هــذا اليــوم األربعــاء املوافــق ‪1434/7/5‬ه ـ ويف متــام الســاعة الثامنــة‬\n      ‫والنصــف صباحـ ًا لــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة بالطائــف‬\n      ‫القائــم بعمــل القســم القضائــي الســابع بنــاء علــى املعاملــة احملالــة مــن‬\n      ‫فضيلــة الرئيــس برقــم ‪ 33629349‬وتاريــخ ‪1433/10/29‬ه ـ واملقيدة يف‬\n      ‫هــذه احملكمــة برقــم ‪ 331914529‬وتاريــخ ‪1433/10/29‬ه ـ افتتحــت‬\n      ‫اجللســة وفيهــا حضــر ‪ ...... ......‬ســعودي اجلنســية بالســجل املدنــي رقــم‬\n      ‫ا عنــه ولــم يقــدم عــذر ًا‬‫‪ ......‬ولــم يحضــر املدعــى عليــه ‪ ......‬وال وكي ـ ً‬\n      ‫تقبلــه احملكمــة وحيــث ســبق أن مت تبليــغ املدعــى عليــه لشــخصه وذلــك‬\n      ‫بخطابنــا رقــم ‪ 331955931‬كمــا تبلــغ املدعــى عليــه لغيــر شــخصه‬\n      ‫حســب خطــاب مديــر مركــز شــرطة الفيصليــة برقــم ‪/4063‬ع‬\n\n‫‪295‬‬\n\f‫يف ‪1433/11/27‬ه ـ واخلطــاب رقــم ‪ 34303205‬يف ‪1434/2/5‬ه ـ‬\n‫وخطــاب مديــر مركــز شــرطة ‪ ........‬برقــم ‪/1230‬ع يف ‪1434/4/1‬ه ـ‬\n‫ورقــم ‪/1950‬ع يف ‪1434/5/29‬ه ـ لــذا قــررت الســير يف نظــر هــذه‬\n‫القضيــة بنــاء علــى املــادة ‪ 2/55‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n‫التنفيذيــة وبســؤال املدعــي عــن دعــواه ادعــى قائ ـاً‪ :‬إن ‪ ......‬اشــترى‬\n‫منــي ســيارة مــن نــوع كابــرس صنــع عــام ‪1989‬م مببلــغ إجمالــي قــدره‬\n‫ا خــال ســنة‬   ‫ثمانيــة وعشــرون ألــف ريــال علــى أن يســلمني املبلــغ كامـ ً‬\n‫علــى دفعتــن الدفعــة األولــى بتاريــخ ‪1427/6/25‬ه ـ مببلــغ أربعــة عشــر‬\n‫ألــف ريــال والدفعــة الثانيــة بتاريــخ ‪1427/12/25‬ه ـ مببلــغ أربعــة عشــر‬\n‫ألــف ريــال وقــد ســددني والــده مــن قيمــة الســيارة املوصوفــة مبلــغ ألفــي‬\n‫ريــال وتبقــى يف ذمتــه لــي مبلــغ ســتة وعشــرون ألــف ريــال وقــد ضمنــه‬\n‫والــده بســداد هــذا املبلــغ أطلــب إثبــات هــذا الضمــان وإلــزام الضامــن‬\n‫بســداد هــذا املبلــغ لــي حــا ًال هكــذا ادعــى وبســؤاله عــن بينتــه أبــرز‬\n‫عــدد كمبيالتــن مــن مطبوعــات معــرض ‪ .....‬لصاحبــه ‪ ......‬حيــث أن‬\n‫الكمبيالــة األولــى صــادرة برقــم ‪ 0449‬يف ‪1427/1/6‬ه ـ مســتحقة‬\n‫الدفــع بتاريــخ ‪1427/6/25‬ه ـ والكمبيالــة الثانيــة صــادرة برقــم ‪0450‬‬\n‫يف ‪1427/1/6‬ه ـ مســتحقة الدفــع بتاريــخ ‪1427/12/25‬ه ـ ثــم طلبــت‬\n‫ا‬‫مــن املدعــي اليمــن علــى صحــة دعــواه فاســتعد بهــا وحلــف قائ ـ ً‬\n‫واهلل العظيــم الــذي ال إلــه إال هــو الــذي يعلــم اجلهــر ومــا يخفــى ويعلــم‬\n‫خائنــة األعــن ومــا تخفــي الصــدور إن ‪ ......‬اشــترى منــي ســيارة مــن نــوع‬\n‫كابــرس صنــع عــام ‪1989‬م مببلــغ إجمالــي قــدره ثمانيــة وعشــرون ألــف‬\n‫ريــال واســتلمت مــن والــده مبلــغ ألفــي ريــال وتبقــى لــي يف ذمتــه مبلــغ ســتة‬\n‫وعشــرون ألــف ريــال واتفقــت معــه علــى الســداد يف ‪1427/12/25‬ه ـ‬\n\n\n                                                                                         ‫‪296‬‬\n\f      ‫وضمنــه والــده ومضــت املــدة ولــم يصلنــي منهــا أي شــيء ولــم أبرئــه‬\n      ‫منهــا أي شــيء واهلل واهلل واهلل هكــذا حلــف فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واســتناد ًا علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n      ‫الشــرعية ولوائحهــا التنفيذيــة ومبــا أن املدعــي حلــف اليمــن التــي طلبــت‬\n      ‫منــه ولقولــه تعالــى (( وملــن جــاء بــه حمــل بعيــر وأنــا بــه زعيــم )) ومبــا أن‬\n      ‫املدعــى عليــه لــم يحضــر ولــم يقــدم عــذر ًا عــن ســبب عــدم احلضــور ولــم‬\n      ‫يقــدم دفاعــه علــى هــذه الدعــوى مــع أنــه تبلــغ لشــخصه ولغيــر شــخصه‬\n      ‫يف جلســات ماضيــة حســب التعليمــات وقــد ذكــر ابــن قدامــه رحمــه‬\n      ‫اهلل تعالــى يف كتابــه الــكايف ‪ 128/6‬مــا نصــه ( فــإن امتنــع اخلصــم‬\n      ‫مــن احلضــور عنــد احلاكــم حكــم عليــه ألنــه لــو لــم يحكــم عليــه جلعــل‬\n      ‫االمتنــاع واالســتتار طريقـ ًا لتضييــع احلقــوق ) أ‪.‬ه ـ وقد ذكر أبو اســحاق‬\n      ‫إبراهيــم بــن حســن يف كتابــه معــن احلــكام علــى القضايــا واألحــكام‬\n      ‫مــا نصــه‪ ( :‬مســألة قــال املــارودي يف تفســير قولــه تعالــى ( وإذا دعــوا‬\n      ‫إلــى اهلل ورســوله ليحكــم بينهــم ) اآليــة دليــل علــى أنــه مــن دعــي إلــى‬\n      ‫حاكــم مــن حــكام املســلمني فعليــه اإلجابــة ويحــرج إن تأخــر وقــد ورد‬\n      ‫عــن احلســن بــن علــي رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫قــال ( مــن دعــي إلــى حاكــم مــن حــكام املســلمني ولــم يجــب فهــو ظالــم‬\n      ‫ال حــق لــه ) أ‪.‬ه ـ لذلــك كلــه فقــد حكمــت بإلــزام املدعــى عليــه الغائــب‬\n      ‫عــن مجلــس احلكــم الشــرعي ‪ ......‬أن يدفــع للمدعــي ‪ ......‬مبلــغ قــدره‬\n      ‫ســتة وعشــرون ألــف ريــال حــا ًال هــذا مــا ظهــر لــي وبــه حكمــت وقــررت‬\n      ‫بعــث نســخة مــن صــك احلكــم للمدعــى عليــه ليقــدم اعتراضــه خــال‬\n      ‫مــدة أقصاهــا ثالثــون يوم ـ ًا مــن تاريــخ التبليــغ باحلكــم وإذا لــم يقــدم‬\n      ‫اعتراضــه خاللهــا فيســقط حقــه يف االعتــراض ويكتســب احلكــم‬\n\n\n‫‪297‬‬\n\f‫القطعيــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                           ‫‪1434/7/5‬ه ـ ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪.:‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ‪ ...... /‬القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد‬\n‫‪34271120‬وتاريــخ ‪1434/7/17‬ه ـ املتضمــن دعــوى ‪ ......‬ضــد ‪......‬‬\n‫واحملكــوم فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة ضبطه تقررت‬\n‫املوافقــة علــى احلكــم ويعــد احلكــم يف حــق املدعــى عليــه حضوريــا‬\n‫اســتنادا للمــادة ‪1/55‬مــن نظــام املرافعــات الشــرعية وصلــى اهلل علــى‬\n                                ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":294,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d606a22c74426496b54c4dc5f26d1457ee54f49900a76f7f6f1feecb76e0597e","normalized_text_hash":"7a2e7e5f2177661be6763f9030af557906541af67485295a83b536958ccc5ff1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p294-34271120"},{"id":"99a05795-7da8-5726-9161-a29fc6db2f8a","document_type":"judgment","category":"judicial","subcategory":"general","title":"كفالة غرم وأداء -وجود دين لوالد املدعي يف ذمة املكفول -املطالبة بسداد الدين -عجز املكفول عن السداد -مصادقة املدعى عليه على كفالة املكفول كفالة حضورية وااللتزام بإحضاره للجهات املختصة خال مدة معينة -عجز الكفيل عن إحضار كفيله -إلزام املدعى عليه (الكفيل) بدفع احلق عن املكفول -للكفيل الرجوع على مكفوله مبا يغرمه عنه .","document_number":"34352048","case_number":"34490550","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/5","year":"1434","subject":"كفالة غرم وأداء -وجود دين لوالد املدعي يف ذمة املكفول -املطالبة بسداد الدين -عجز املكفول عن السداد -مصادقة املدعى عليه على كفالة املكفول كفالة حضورية وااللتزام بإحضاره للجهات املختصة خال مدة معينة -عجز الكفيل عن إحضار كفيله -إلزام املدعى عليه (الكفيل) بدفع احلق عن املكفول -للكفيل الرجوع على مكفوله مبا يغرمه عنه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34352048 :‬تاريخه‪1434/11/5 :‬هـ‬\n                         ‫رقم الدعوى‪34490550 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34368656‬تاريخه‪1434/11/24 :‬هـ‬\n\n\n      ‫كفالــة غــرم وأداء ‪ -‬وجــود ديــن لوالــد املدعي يف ذمة املكفول ‪ -‬املطالبة‬\n      ‫بســداد الديــن ‪ -‬عجــز املكفــول عــن الســداد ‪ -‬مصادقــة املدعــى عليــه‬\n      ‫علــى كفالــة املكفــول كفالــة حضوريــة وااللتــزام بإحضــاره للجهــات‬\n      ‫املختصــة خــال مــدة معينــة ‪ -‬عجــز الكفيــل عــن إحضــار كفيلــه‬\n      ‫‪ -‬إلــزام املدعــى عليــه (الكفيــل) بدفــع احلــق عــن املكفــول ‪ -‬للكفيــل‬\n                                    ‫الرجــوع علــى مكفولــه مبــا يغرمــه عنــه ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم‪( :‬الزعيــم غــارم) أخرجــه الترمــذي‬\n                    ‫(‪ )1265‬وصححــه األلبانــي يف إرواء الغليــل (‪.)1412‬‬\n      ‫‪ .2‬جــاء يف املغنــي ‪ ( 415 /4‬فإنــه متــى تعــذر علــى الكفيــل إحضــار‬\n      ‫املكفــول بــه مــع حياتــه أو امتنــع مــن إحضــاره لزمــه مــا عليــه ‪...‬ألنهــا‬\n                        ‫أحــد نوعــي الكفالــة فوجــب بهــا الغــرم كالكفالــة باملــال)‪.‬‬\n      ‫‪ .3‬جــاء يف املبــدع البــن مفلــح (‪( )245 /4‬وألنهــا أي الكفالــة اســتيثاق‬\n                                 ‫يلــزم الكفيــل مــا علــى املكفــول بــه عنــد تعــذر إحضــاره)‪.‬‬\n      ‫يها)‬ ‫‪ .4‬وقد جاء يف كشاف القناع (‪ )380 /3‬ما نصه‪َ ( (:‬و ِإ ْن َل ْم ُي ْع َل ْم فِ َ‬\n                      ‫(خ َبـ ُـر ُه) أ َْي‪ْ :‬الَ ْك ُفــولِ ِبـ ِه ( َل ِز َمـ ُه) أ َْي‪ :‬ا ْل َكفِ يـ َـل ِّ‬\n      ‫(الديـ ُـن مِ ـ ْـن‬                                                                                       ‫أ َْي‪ِ :‬ف ا ْل َغ ْي َبـ ِة َ‬\n                    ‫ب ْو ِضعِ هِ‪. )..‬‬                                                    ‫َغ ْيـ ِر ْإم َهــالٍ ) إ ْذ َل فَ ا ِئـ َـد َة ِف ْ ِ‬\n                                        ‫ال ْم َهــالِ َمـ َـع َعـ َـد ِم ا ْلعِ ْلـ ِـم ِ َ‬\n\n\n\n‫‪299‬‬\n\f‫ادعــى املدعــي وكالــة أن لوالــده ديــن يف ذمــة مكفــول املدعــى عليــه‬\n‫‪ ،‬حيــث تقــدم موكلــه بدعــوى ضــد مكفولــه مبطالبتــه مببلــغ قــدره‬\n‫ثالثمائــة واثنــا عشــر ألف ـ ًا ومائتــان وســبعة وثمانــون ريــا ًال وصــدر عليــه‬\n‫حكــم لصالــح موكلــه بإلزامــه بســداد املبلــغ ومت إيــداع مكفــول‬\n‫املدعــى عليــه الســجن بعــد عجــزه عــن ســداد املبلــغ اســتظهار ًا حلالــه وقــد‬\n‫أفــرج عنــه بكفالــة حضوريــة ملــدة خمســة عشــر يوم ـ ًا ثــم هــرب وقــد‬\n‫عجــز املدعــى عليــه عــن إحضــاره ‪ ،‬صــادق املدعــى عليــه علــى الدعــوى‬\n‫‪ ،‬جــرى االطــاع علــى ورقــة كفالــة املدعــى عليــه وقــد نــص فيهــا (وأنــه‬\n‫إذا لــم يحضــر مكفولــه يكــون مســؤوال عمــا يترتــب بحقــه مــن اجلــزاء‬\n‫ويكــون ملتزمــا بكافــة احلقــوق أو اجلــزاءات املترتبــة عليــه يف حــال‬\n‫عجــزه عــن إحضــاره يف الوقــت احملــدد ) مبــا أن املدعــى عليــه قــد قــرر‬\n‫عجــزه عــن إحضــار مكفولــه ‪ ،‬وملــا قــرره أهــل العلــم مــن لــزوم الديــن‬\n‫علــى كفيــل البــدن ( الكفيــل احلضــوري) إذا تعــذر إحضــار مكفولــه‬\n‫وعجــز عــن ذلــك ‪ ،‬احلكــم علــى املدعــى عليــه بــأن يدفــع احلــق الــذي‬\n‫علــى مكفولــه والبالــغ قــدره (‪ )312287‬ثالثمائــة واثنــا عشــر ألف ـ ًا‬\n‫ومائتــان وســبعة وثمانــون ريــاال للمدعــي أصالــة ‪ ،‬إفهــام املدعــى عليــه‬\n‫بــأن لــه الرجــوع علــى مكفولــه مبــا غرمــه عنــه ‪ ،‬اعتــرض املدعــى عليــه‬\n‫بــدون الئحــة ‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة األولــى مبحكمــة‬\n                                                  ‫االســتئناف مبنطقــة اجلــوف ‪.‬‬\n\n\n\n\n                                                                                        ‫‪300‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n      ‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعرعــر برقــم ‪ 34490550‬وتاريــخ ‪ 1434/11/03‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 342494714‬وتاريــخ ‪ 1434/11/03‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافــق‪ 1434/11/03‬ه ـ افتتحــت اجللســة الســاعة ‪01 : 00‬‬\n      ‫وفيهــا حضــر ‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬‬\n      ‫بصفتــه وكيــا عــن والــده ‪.......‬ســعودي بالهويــة رقــم ‪.......‬مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــة عــدل عرعــر برقــم ‪ 3334051‬وتاريــخ‬\n      ‫‪1433/1/18‬ه ـ واملخــول لــه فيهــا باملطالبــة واملرافعــة واملخاصمــة‬\n      ‫وإقامــة الدعــاوى واإلقــرار واإلنــكار والصلــح مدعيــا علــى احلاضــر‬\n      ‫ا يف دعــواه عليــه‪ :‬تقــدم والــدي‬   ‫معــه ‪.......‬ســعودي بالهويــة رقــم ‪.......‬قائـ ً‬\n      ‫بدعــوى ضــد ‪ .......‬ســعودي بالهويــة رقــم ‪.......‬قيــدت بهــذه احملكمــة‬\n      ‫برقــم ‪ 331228714‬وتاريــخ ‪1433/6/30‬ه ـ وأحيلــت إلــى هــذا املكتــب‬\n      ‫برقــم ‪33436261‬وتاريــخ ‪1433/6/30‬ه ـ تتضمــن بــأن املذكــور كان‬\n      ‫معقبــا يف مؤسســة والــدي مجموعــة ‪.......‬واململوكــة لــه مبوجــب الســجل‬\n      ‫التجــاري والصــادر مــن فــرع وزارة التجــارة يف عرعــر برقــم ‪.......‬وتاريــخ‬\n      ‫‪1412/1/5‬ه ـ وتبــن لوالــدي بعــد مراجعــة احلســابات بــأن لــه يف ذمــة‬\n      ‫املذكــور مبلغ ـ ًا وقــدره (‪ )312287‬ثالثمائــة واثنــا عشــر ألف ـ ًا ومائتــان‬\n      ‫وســبعة وثمانــون ريــا ًال وقــد أقــر املذكــور باملبلــغ وصــدر حكــم مــن‬\n      ‫فضيلــة القاضــي بهــذه احملكمــة ســابق ًا الشــيخ ‪.......‬بالصــك رقــم‬\n      ‫‪ 33381890‬وتاريــخ ‪1433/8/17‬ه ـ يقضــي بإلــزام املذكــور دفــع‬\n\n‫‪301‬‬\n\f‫كامــل املبلــغ لوالــدي وقــد عجــز املذكــور عــن ســداد املبلــغ فتــم‬\n‫إيداعــه الســجن اســتظهار ًا حلالــه وبعــد مــدة أفــرج عنــه القاضــي نفســه‬\n‫بتاريــخ ‪1434/5/1‬ه ـ ملــدة خمســة عشــر يومــا بالكفالــة احلضوريــة‬\n‫املشــددة وقــد انتهــت املــدة املذكــورة وتهــرب املذكــور مــن احلضــور‬\n‫إلــى إدارة تنفيــذ األحــكام احلقوقيــة وقــد كفلــه هــذا احلاضــر كفالــة‬\n‫حضوريــة وعجــز عــن إحضــاره ولــذا أطلــب إلزامــه مبــا يترتــب علــى‬\n‫الكفالــة احلضوريــة وذلــك بســداد مــا يف ذمــة مكفولــه لوالــدي هــذه‬\n‫دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائ ـاً‪ :‬صحيــح مــا‬\n‫ذكــره املدعــي وكالــة مــن أننــي كفلــت ‪.......‬كفالــة حضوريــة بعــد‬\n‫اإلفــراج عنــه بتاريــخ ‪1434/5/1‬ه ـ وقــد التزمــت بإحضــاره بعــد خمســة‬\n‫عشــر يومــا مــن تاريخــه للجهــة املختصــة وقــد انتهــت املــدة وعجــزت عــن‬\n‫إحضــاره لكونــه متهربــا وتعــذر علــي معرفــة مــكان إقامتــه وكنــت‬\n‫أعلــم بــأن املبلــغ احملكــوم بــه علــى املذكــور قــدره (‪ )312287‬ثالثمائــة‬\n‫واثنــا عشــر ألف ـ ًا ومائتــان وســبعة وثمانــون ريــاال هكــذا أجــاب هــذا‬\n‫وقــد جــرى االطــاع علــى الصــك الصــادر مــن صاحــب الفضيلــة القاضي‬\n‫الســلف الشــيخ ‪.......‬برقــم ‪ 33381890‬وتاريــخ ‪1433/8/17‬ه ـ فوجدتــه‬\n‫كمــا ذكــره املدعــي كمــا جــرى االطــاع علــى أوراق املعاملــة املقيــدة‬\n‫بهــذه احملكمــة برقــم ‪ 331228714‬وتاريــخ ‪1433/6/30‬ه ـ واحملالــة‬\n‫إلــى مكتبنــا برقــم ‪33436261‬وتاريــخ ‪1433/6/30‬ه ـ فوجــدت‬\n‫كفالــة املدعــى عليــه ل‪ .......‬كفالــة حضوريــة مدونــه علــى مطبوعــات‬\n‫إدارة تنفيــذ األحــكام احلقوقيــة ومؤرخــه بتاريــخ ‪1434/5/1‬ه ـ وأنــه‬\n‫إذا لــم يحضــر مكفولــه يكــون مســؤوال عمــا يترتــب بحقــه مــن‬\n‫اجلــزاء ويكــون ملتزمــا بكافــة احلقــوق أو اجلــزاءات املترتبــة عليــه يف‬\n\n\n                                                                                  ‫‪302‬‬\n\f      ‫حــال عجــزه عــن إحضــاره يف الوقــت احملــدد أ‪.‬ه ـ كمــا وجــدت إقــرار ًا‬\n      ‫للمدعــى عليــه مؤرخـ ًا يف ‪1434/5/1‬ه ـ يتضمــن بأنــه ســيقوم بإحضــار‬\n      ‫مكفولــه ‪.......‬بعــد خمســة عشــر يوم ـ ًا مــن تاريــخ اإلقــرار أ‪.‬ه ـ كمــا‬\n      ‫وجــدت باملعاملــة ثمانيــة محاضــر اتصــال علــى املدعــى عليــه مــن أجــل‬\n      ‫إحضــار مكفولــه أ‪.‬ه ـ كمــا وجــدت للمدعــى عليــه إقــرار ًا مؤرخ ـ ًا يف‬\n      ‫‪1434/6/4‬ه ـ يتضمــن اســتعداده بإحضــار مكفولــه يف يــوم الســبت‬\n      ‫‪1434/6/10‬ه ـ أ‪.‬ه ـ كمــا جــرى االطــاع علــى احملضــر الصــادر منــي‬\n      ‫واملتضمــن بــأن املدعــى عليــه حضــر لــدي بتاريــخ ‪1434/10/15‬ه ـ‬\n      ‫واســتعد بإحضــار مكفولــه‪....... /‬قبــل يــوم اخلميــس ‪1434/10/29‬ه ـ‬\n      ‫وأنــه جــرى إعــذار املذكــور وإفهامــه بأنــه يف حــال عجــزه عــن إحضــار‬\n      ‫مكفولــه فيلــزم بســداد مــا يف ذمــة مكفولــه خلصمــه ‪.......‬ففهــم ذلــك‬\n      ‫أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى‬\n                                         ‫أوراق املعاملــة ومبــا أنــه ظهــر لــي مــا يلــي‪:‬‬\n      ‫أوالً‪ :‬أن الطرفــن تصادقــا علــى أن يف ذمــة املدعــو‪....... /‬للمدعــي‬\n      ‫أصالــة مبلغ ـ ًا وقــدره (‪ )312287‬ثالثمائــة واثنــا عشــر ألف ـ ًا ومائتــان‬\n                                                                ‫وســبعة وثمانــون ريــاال‪.‬‬\n      ‫ثاني ـاً‪ :‬أن الطرفــن تصادقــا علــى أن املدعــو‪....... /‬عجــز عــن ســداد مــا‬\n      ‫يف ذمتــه للمدعــي أصالــة وقــد مت إيــداع املذكــور يف الســجن اســتظهار ًا‬\n                                                                                        ‫حلالــه‪.‬‬\n      ‫ثالث ـاً‪ :‬أن الطرفــن تصادقــا علــى أن املدعــو‪....... /‬أطلــق ســراحه‬\n      ‫بالكفالــة احلضوريــة ملــدة خمســة عشــر يومــا اعتبــارا مــن تاريــخ‬\n                                                                          ‫‪1434/5/1‬ه ـ ‪.‬‬\n      ‫رابعـاً‪ :‬أن املدعــى عليــه صــادق علــى كفالــة ‪.......‬كفالــة حضوريــة وأنــه‬\n\n\n‫‪303‬‬\n\f‫ملتــزم بإحضــاره للجهــات املختصــة بعــد خمســة عشــر يومــا اعتبــار ًا مــن‬\n                             ‫تاريــخ ‪1434/5/1‬ه ـ وحلــت املــدة ولــم يحضــر مكفولــه‪.‬‬\n‫خامس ـاً‪ :‬أن مت إمهــال املدعــى عليــه إلحضــار مكفولــه مــن قبلــي ملــدة‬\n‫خمســة عشــر يوم ـ ًا اعتبــارا مــن تاريــخ ‪1434/10/15‬ه ـ وانتهــت املهلــة‬\n                                                                                                      ‫ولــم يحضــر مكفولــه‪.‬‬\n                           ‫سادساً‪ :‬أن املدعى عليه قرر عجزه عن إحضار مكفوله‪.‬‬\n‫ســابعاً‪ :‬أن املدعــي وكالــة يطلــب إلــزام املدعــى عليــه بســداد مــا يف ذمــة‬\n‫مكفولــه لوالــده‪ .‬فتأسيسـ ًا علــى مــا ســبق ولعمــوم قولــه صلــى اهلل عليــه‬\n‫وســلم‪( :‬الزعيــم غــارم) أخرجــه الترمــذي (‪ )1265‬وصححــه األلبانــي‬\n‫يف إرواء الغليــل (‪ )1412‬وملــا قــرره أهــل العلــم مــن أنــه يلــزم الكفيــل‬\n‫إحضــار مكفولــه يف كفالــة البــدن‪ ،‬ويف حــال عجــزه عــن إحضــاره‬\n‫يلزمــه مــا علــى مكفولــه قــال ابــن قدامــة رحمــه اهلل‪( :‬الكفالــة بالنفس‬\n‫صحيحــة يف قــول أكثــر أهــل العلــم هــذا مذهب شــريح و مالك و الثوري‬\n‫و الليــث و أبــي حنيفــة‪...‬ألن مــا وجــب تســليمه بعقــد وجــب تســليمه بعقــد‬\n‫الكفالــة كاملــال إذا ثبــت هــذا فإنــه متــى تعــذر علــى الكفيــل إحضــار‬\n‫املكفــول بــه مــع حياتــه أو امتنــع مــن إحضــاره لزمــه مــا عليــه ‪...‬ألنهــا‬\n‫أحــد نوعــي الكفالــة فوجــب بهــا الغــرم كالكفالــة باملــال) املغنــي (‪/4‬‬\n‫‪ )415‬وقال ابن مفلح‪ (:‬وألنها ـ أي الكفالة ـ اســتيثاق يلزم الكفيل ما‬\n‫علــى املكفــول بــه عنــد تعــذر إحضــاره) املبــدع (‪ )245 /4‬وقــد جــاء يف‬\n‫(و ِإنْ َلـ ْـم ُي ْع َلـ ْـم فِ ي َهــا) َأ ْي‪ِ :‬ف ا ْل َغ ْي َبـ ِة‬\n                                                                   ‫كشــاف القنــاع (‪ )380 /3‬مــا نصــه‪َ (:‬‬\n‫(الديـ ُـن مِ ــنْ غَ ْيـ ِـر ْإم َهــالٍ )‬\n                                        ‫كفِ يــلَ ِّ‬             ‫َك ُفــولِ ِبـ ِه (ل َِز َمـ ُه) َأ ْي‪ :‬ا ْل َ‬     ‫(خ َبـ ُـر ُه) َأ ْي‪ْ :‬ال ْ‬\n                                                                                                                                             ‫َ‬\n‫(ف ـ ِإنْ ) ُع ِلـ َـم َم ْو ِض ُع ـ ُه‬\n                                      ‫ب ْو ِض ِع ـ ِه َ‬                                                          ‫ْإذ َل َفا ِئـ َـد َة ِف ْ ِ‬\n                                                              ‫ال ْم َهــالِ َمـ َـع َعـ َـد ِم ا ْل ِع ْلـ ِـم ِ َ‬\n  ‫(إمــا ِل َتـ َـوانٍ‬\n                   ‫َك ُفــولَ ِب ـ ِه َّ‬  ‫(و َلـ ْـم ُي ْح ِضـ ْـر ُه) َأ ْي‪ْ :‬ال ْ‬          ‫كفِ يــلُ إ َل ْي ـ ِه َ‬ ‫(م َضــى) ا ْل َ‬    ‫َو َ‬\n\n                                                                                                                                                  ‫‪304‬‬\n\f      ‫اخت َِفا ِئ ـ ِه َأ ْو؛ ِل ْم ِت َناعِ ـهِ‪َ ،‬أ ْو ِل َغ ْيـ ِـر َذ ِلـ َـك)‬      ‫(و ْ‬ ‫َك ُفــولِ ِب ـ ِه َ‬         ‫َأ ْو ِل َه َر ِب ـهِ) َأ ْي‪ْ :‬ال ْ‬\n        ‫كفِ يــلَ‬   ‫ـار ُه َمـ َـع َح َيا ِتـ ِه ل َِز َمـ ُه) َأ ْي‪ :‬ا ْل َ‬ ‫إح َضـ ُ‬    ‫ـث َت َعـ َّـذ َر ْ‬     ‫كــذِ ي ُسـ ْل َطانٍ ( ِب َح ْيـ ُ‬          ‫َ‬\n         ‫ك َفا َلـ ِة َف َو َجـ َـب ا ْل ُغـ ْـر ُم ِب َهــا إ َذنْ‬‫)‪...‬ل َّن َهــا َأ َحـ ُـد ن َْو َعـ ْـي ا ْل َ‬\n                                                                                                             ‫الد ْي ِن ِ َ‬    ‫(مــا َع َل ْيـ ِه مِ ــنْ َّ‬\n                                                                                                                                                         ‫َ‬\n      ‫َك ُفولِ ِب ِه‬     ‫الــالُ ِب ِإ ْح َضــا ِر ْال ْ‬       ‫كفِ يـ ِـل ْ َ‬\n                                                                            ‫الــالِ َو َل َي ْسـ ُـق ُط َعــنْ ا ْل َ‬           ‫ك َفا َلـ ِة ِب ْ َ‬\n                                                                                                                                                  ‫كا ْل َ‬  ‫َ‬\n      ‫َصــا) لذلــك كلــه فقــد ثبــت لــدي صحــة الدعــوى‬                                                     ‫َب ْعـ َـد ا ْل َو ْقـ ِـت ْال َُسـ َّـمى ن ًّ‬\n      ‫وأن املدعــى عليــه ‪ .......‬عاجــز عــن إحضــار مكفولــه املذكــور بعــد‬\n      ‫إعطائــه املهلــة الكافيــة كمــا هــو مفصــل أعــاه فلــذا فقــد حكمــت‬\n      ‫علــى املدعــى عليــه بــأن يدفــع احلــق الــذي علــى مكفولــه والبالــغ قــدره‬\n      ‫(‪)312287‬ثالثمائــة واثنــا عشــر ألف ـ ًا ومائتــان وســبعة وثمانــون ريــاال‬\n      ‫للمدعــي أصالــة وأفهمــت املدعــى عليــه بــأن لــه الرجــوع علــى مكفولــه‬\n      ‫مبــا يغرمــه عنــه للمدعــي وبإعــان احلكــم علــى املدعــى عليــه قــرر‬\n      ‫اعتراضــه علــى احلكــم بــدون الئحــة وســيجري التهميــش علــى الصــك‬\n      ‫رقــم ‪ 33381890‬وتاريــخ ‪1433/8/17‬ه ـ مبضمــون احلكــم أعــاه بعــد‬\n      ‫اكتســابه القطعيــة واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                                                                     ‫حــرر يف ‪1434/11/03‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n      ‫األولــى يف محكمــة االســتئناف مبنطقــة اجلوف علــى املعاملة الواردة من‬\n      ‫فضيلــة رئيــس احملكمــة العامــة يف عرعــر برقــم ‪ 342494714‬وتاريــخ‬\n      ‫‪1434/11/9‬ه ـ املقيــدة لــدى هذه احملكمة برقــم ‪ 342620747‬وتاريخ‬\n      ‫‪1434/11/19‬ه ـ املرفــق بهــا الصــك الصـ ــادر مــن فضيل ـ ــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪......./‬برقــم ‪ 34352048‬وتاريــخ ‪1434/11/5‬هـ ـ‬\n      ‫اخلــاص بدعــوى ‪......./‬وكالــة ضــد ‪......./‬يف مطالبــة ماليــة وقــد تضمــن‬\n      ‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك‬\n\n\n‫‪305‬‬\n\f‫وصــورة ضبطــه وأوراق املعاملــة فــإن الدائــرة تقــرر املصادقــة علــى‬\n‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                      ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪306‬‬\n\f307\n\f308\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":299,"source_page_end":308,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"91670d96332f94579577720216dd1be085c53fde00fa075d1bf9488ab3977d08","normalized_text_hash":"9452df9351382d77de055e2edb80e